  1→import {
  2→  Injectable,
  3→  HttpException,
  4→  HttpStatus,
  5→  BadRequestException,
  6→  ConflictException,
  7→  Logger,
  8→  Inject,
  9→  forwardRef,
 10→} from '@nestjs/common';
 11→import { InjectRepository } from '@nestjs/typeorm';
 12→import { Repository } from 'typeorm';
 13→import { FolderIpns } from './entities/folder-ipns.entity';
 14→import {
 15→  PublishIpnsDto,
 16→  PublishIpnsEntryDto,
 17→  PublishIpnsResponseDto,
 18→  BatchPublishIpnsDto,
 19→  BatchPublishIpnsResponseDto,
 20→} from './dto';
 21→import { RepublishService } from '../republish/republish.service';
 22→import { DelegatedRoutingClient } from './delegated-routing.client';
 23→import { MetricsService } from '../metrics/metrics.service';
 24→import { parseIpnsRecord } from './ipns-record-parser';
 25→
 26→@Injectable()
 27→export class IpnsService {
 28→  private readonly logger = new Logger(IpnsService.name);
 29→
 30→  constructor(
 31→    @InjectRepository(FolderIpns)
 32→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 33→    private readonly delegatedRouting: DelegatedRoutingClient,
 34→    @Inject(forwardRef(() => RepublishService))
 35→    private readonly republishService: RepublishService,
 36→    private readonly metricsService: MetricsService
 37→  ) {}
 38→
 39→  /**
 40→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 41→   * and track the folder in the database for TEE republishing
 42→   */
 43→  async publishRecord(
 44→    userId: string,
 45→    dto: PublishIpnsDto | PublishIpnsEntryDto,
 46→    recordType: 'folder' | 'file' = 'folder'
 47→  ): Promise<PublishIpnsResponseDto> {
 48→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
 49→      operation: 'publish',
 50→      source: '',
 51→    });
 52→    let result = 'success';
 53→
 54→    try {
 55→      // Validate base64 record
 56→      let recordBytes: Uint8Array;
 57→      try {
 58→        recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 59→      } catch {
 60→        throw new BadRequestException('Invalid base64-encoded record');
 61→      }
 62→
 63→      // Save to DB first so resolve always has a fallback, even if delegated
 64→      // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 65→      const folder = await this.upsertFolderIpns(
 66→        userId,
 67→        dto.ipnsName,
 68→        dto.metadataCid,
 69→        dto.encryptedIpnsPrivateKey,
 70→        dto.keyEpoch,
 71→        recordType,
 72→        dto.expectedSequenceNumber
 73→      );
 74→
 75→      // Publish to delegated routing API (best-effort — DB is the reliable source)
 76→      const publishStart = process.hrtime.bigint();
 77→      let publishOutcome = 'success';
 78→      try {
 79→        await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
 80→      } catch (error) {
 81→        result = 'delegated_error';
 82→        publishOutcome = 'error';
 83→        this.logger.warn(
 84→          `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 85→        );
 86→      } finally {
 87→        const publishElapsed = Number(process.hrtime.bigint() - publishStart) / 1e9;
 88→        this.metricsService.ipnsPublishDuration.observe(
 89→          { outcome: publishOutcome },
 90→          publishElapsed
 91→        );
 92→      }
 93→
 94→      return {
 95→        success: true,
 96→        ipnsName: dto.ipnsName,
 97→        sequenceNumber: folder.sequenceNumber,
 98→      };
 99→    } catch (error) {
100→      result = 'error';
101→      throw error;
102→    } finally {
103→      endTimer({ result });
104→    }
105→  }
106→
107→  /**
108→   * Batch publish multiple IPNS records with concurrency-limited processing.
109→   * Supports partial success: individual record failures do not fail the batch.
110→   * Processes up to 10 records concurrently.
111→   */
112→  async publishBatch(
113→    userId: string,
114→    dto: BatchPublishIpnsDto
115→  ): Promise<BatchPublishIpnsResponseDto> {
116→    const results: PublishIpnsResponseDto[] = [];
117→    let totalSucceeded = 0;
118→    let totalFailed = 0;
119→
120→    const CONCURRENCY = 10;
121→
122→    // Process records in batches of CONCURRENCY, delegating to publishRecord
123→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
124→      const batch = dto.records.slice(i, i + CONCURRENCY);
125→
126→      const settled = await Promise.allSettled(
127→        batch.map((entry) => this.publishRecord(userId, entry, entry.recordType ?? 'folder'))
128→      );
129→
130→      for (let j = 0; j < settled.length; j++) {
131→        const result = settled[j];
132→        if (result.status === 'fulfilled') {
133→          results.push(result.value);
134→          totalSucceeded++;
135→        } else {
136→          const reason = result.reason;
137→          // If any record (especially a folder record) has a conflict, fail the entire batch
138→          if (reason instanceof ConflictException) {
139→            throw reason;
140→          }
141→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
142→          this.logger.warn(
143→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
144→          );
145→          results.push({
146→            success: false,
147→            ipnsName,
148→            sequenceNumber: '0',
149→          });
150→          totalFailed++;
151→        }
152→      }
153→    }
154→
155→    return { results, totalSucceeded, totalFailed };
156→  }
157→
158→  /**
159→   * Create or update a folder/file IPNS entry.
160→   * Handles both folder metadata and per-file metadata IPNS records.
161→   */
162→  private async upsertFolderIpns(
163→    userId: string,
164→    ipnsName: string,
165→    metadataCid: string,
166→    encryptedIpnsPrivateKey?: string,
167→    keyEpoch?: number,
168→    recordType: 'folder' | 'file' = 'folder',
169→    expectedSequenceNumber?: string
170→  ): Promise<FolderIpns> {
171→    const existing = await this.getFolderIpns(userId, ipnsName);
172→
173→    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
174→    if (existing && expectedSequenceNumber !== undefined) {
175→      const expected = BigInt(expectedSequenceNumber);
176→      const current = BigInt(existing.sequenceNumber);
177→      if (expected !== current) {
178→        throw new ConflictException({
179→          statusCode: 409,
180→          message: 'Sequence number mismatch: folder was modified by another device',
181→          currentSequenceNumber: existing.sequenceNumber,
182→          expectedSequenceNumber,
183→        });
184→      }
185→    }
186→
187→    if (existing) {
188→      // Update existing entry
189→      existing.latestCid = metadataCid;
190→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
191→      existing.recordType = recordType;
192→      existing.updatedAt = new Date();
193→
194→      // Only update encrypted key if provided (e.g., on key rotation)
195→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
196→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
197→        existing.keyEpoch = keyEpoch;
198→      }
199→
200→      const saved = await this.folderIpnsRepository.save(existing);
201→
202→      // Auto-enroll for TEE republishing when encrypted key is provided
203→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
204→        this.republishService
205→          .enrollFolder(
206→            userId,
207→            ipnsName,
208→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
209→            keyEpoch,
210→            metadataCid,
211→            saved.sequenceNumber
212→          )
213→          .catch((err) =>
214→            this.logger.warn(
215→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
216→            )
217→          );
218→      }
219→
220→      return saved;
221→    }
222→
223→    // Create new entry — sequence starts at '1' to match the IPNS record
224→    // the client signed (clients compute newSeq = 0n + 1n = 1n for first publish).
225→    const folder = this.folderIpnsRepository.create({
226→      userId,
227→      ipnsName,
228→      latestCid: metadataCid,
229→      sequenceNumber: '1',
230→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
231→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
232→        : null,
233→      keyEpoch: keyEpoch ?? null,
234→      isRoot: false, // Root folder is tracked in Vault entity
235→      recordType,
236→    });
237→
238→    const saved = await this.folderIpnsRepository.save(folder);
239→
240→    // Auto-enroll for TEE republishing when encrypted key is provided
241→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
242→      this.republishService
243→        .enrollFolder(
244→          userId,
245→          ipnsName,
246→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
247→          keyEpoch,
248→          metadataCid,
249→          saved.sequenceNumber
250→        )
251→        .catch((err) =>
252→          this.logger.warn(
253→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
254→          )
255→        );
256→    }
257→
258→    return saved;
259→  }
260→
261→  /**
262→   * Get a folder IPNS entry by user and IPNS name
263→   */
264→  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
265→    return this.folderIpnsRepository.findOne({
266→      where: { userId, ipnsName },
267→    });
268→  }
269→
270→  /**
271→   * Get all folder IPNS entries for a user (for TEE republishing)
272→   */
273→  async getAllFolderIpns(userId: string): Promise<FolderIpns[]> {
274→    return this.folderIpnsRepository.find({
275→      where: { userId },
276→      order: { createdAt: 'ASC' },
277→    });
278→  }
279→
280→  /**
281→   * Resolve an IPNS name to its current CID via delegated routing,
282→   * falling back to the DB-cached CID when delegated routing is unavailable
283→   * or when the record is not found in the DHT.
284→   * Returns null if the IPNS name is not found anywhere (404)
285→   */
286→  async resolveRecord(ipnsName: string): Promise<{
287→    cid: string;
288→    sequenceNumber: string;
289→    signatureV2?: string;
290→    data?: string;
291→    pubKey?: string;
292→  } | null> {
293→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
294→      operation: 'resolve',
295→    });
296→    let timerResult = 'success';
297→    let timerSource = 'network';
298→    const startTime = process.hrtime.bigint();
299→    let source = 'network';
300→    let resolveFound = false;
301→
302→    try {
303→      let result: {
304→        cid: string;
305→        sequenceNumber: string;
306→        signatureV2?: string;
307→        data?: string;
308→        pubKey?: string;
309→      } | null = null;
310→
311→      try {
312→        const recordBytes = await this.delegatedRouting.resolve(ipnsName);
313→        if (recordBytes) {
314→          result = this.parseIpnsRecordBytes(recordBytes);
315→          this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
316→        }
317→      } catch (error) {
318→        // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
319→        if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
320→          this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
321→          timerResult = 'error';
322→          source = 'db_cache';
323→        } else {
324→          timerResult = 'error';
325→          throw error;
326→        }
327→      }
328→
329→      // Always check DB cache — it's written synchronously during publish
330→      // and may be ahead of the network (delegated routing can serve stale records)
331→      const cached = await this.folderIpnsRepository.findOne({
332→        where: { ipnsName },
333→      });
334→
335→      if (result && cached?.latestCid) {
336→        // Both sources available — prefer the one with the higher sequence number
337→        const networkSeq = BigInt(result.sequenceNumber);
338→        const dbSeq = BigInt(cached.sequenceNumber);
339→        if (dbSeq > networkSeq) {
340→          this.logger.log(
341→            `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
342→          );
343→          timerSource = 'db';
344→          source = 'network_stale';
345→          resolveFound = true;
346→          return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
347→        }
348→        timerSource = 'network';
349→        resolveFound = true;
350→        return result;
351→      }
352→
353→      if (result) {
354→        timerSource = 'network';
355→        resolveFound = true;
356→        return result;
357→      }
358→
359→      // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
360→      if (cached?.latestCid) {
361→        this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
362→        timerSource = 'db';
363→        source = 'db_cache';
364→        resolveFound = true;
365→        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
366→      }
367→
368→      return null;
369→    } catch (error) {
370→      timerResult = 'error';
371→      throw error;
372→    } finally {
373→      endTimer({ result: timerResult, source: timerSource });
374→      if (resolveFound) {
375→        const elapsed = Number(process.hrtime.bigint() - startTime) / 1e9;
376→        this.metricsService.ipnsResolveDuration.observe({ source, outcome: timerResult }, elapsed);
377→      }
378→    }
379→  }
380→
381→  /**
382→   * Parse an IPNS record to extract CID and sequence number
383→   * Uses inline protobuf decoder — no external dependencies
384→   */
385→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
386→    cid: string;
387→    sequenceNumber: string;
388→    signatureV2?: string;
389→    data?: string;
390→    pubKey?: string;
391→  } {
392→    try {
393→      const record = parseIpnsRecord(recordBytes);
394→
395→      // Extract CID from the Value field (format: /ipfs/<cid>)
396→      const valuePath = record.value;
397→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
398→      if (!cidMatch) {
399→        this.logger.error('Failed to extract CID from IPNS record value');
400→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
401→      }
402→
403→      const cid = cidMatch[1];
404→      const sequenceNumber = String(record.sequence ?? 0n);
405→
406→      // Base64-encode signature fields if present
407→      const signatureV2 = record.signatureV2
408→        ? Buffer.from(record.signatureV2).toString('base64')
409→        : undefined;
410→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
411→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
412→
413→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
414→      return { cid, sequenceNumber, signatureV2, data, pubKey };
415→    } catch (error) {
416→      if (error instanceof HttpException) {
417→        throw error;
418→      }
419→      this.logger.error(`Failed to parse IPNS record: ${error}`);
420→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
421→    }
422→  }
423→}
