  1→/**
  2→ * @cipherbox/sdk - Bin operations
  3→ *
  4→ * Extracted from: apps/web/src/services/bin.service.ts (962 LOC)
  5→ * All Zustand store access replaced with explicit parameters.
  6→ *
  7→ * Bin operations manage the recycle bin lifecycle:
  8→ * - addToBin: soft-delete (remove from folder, add to bin)
  9→ * - restoreFromBin: undo soft-delete (remove from bin, add back to folder)
 10→ * - permanentDeleteFromBin: hard-delete with CID cleanup
 11→ * - emptyBin: permanently delete all bin entries
 12→ * - loadBin: load current bin metadata from IPNS
 13→ *
 14→ * Each function takes explicit params instead of reading from stores.
 15→ */
 16→
 17→import type { SdkContext, TeeKeys } from '@cipherbox/sdk-core';
 18→import * as sdkCore from '@cipherbox/sdk-core';
 19→import {
 20→  encryptBinMetadata,
 21→  decryptBinMetadata,
 22→  deriveBinIpnsKeypair,
 23→  type BinEntry,
 24→  type RecycleBinMetadata,
 25→  type FolderChild,
 26→  type FilePointer,
 27→  type FolderEntry,
 28→} from '@cipherbox/core';
 29→import { bytesToHex, hexToBytes, wrapKey } from '@cipherbox/crypto';
 30→import type { FolderTree } from '../state/folder-tree';
 31→
 32→/** Current bin metadata version. */
 33→const BIN_METADATA_VERSION = 'v1' as const;
 34→
 35→/**
 36→ * Context for bin operations. Replaces Zustand store access.
 37→ */
 38→export type BinOperationContext = {
 39→  ctx: SdkContext;
 40→  userPrivateKey: Uint8Array;
 41→  userPublicKey: Uint8Array;
 42→  rootFolderKey: Uint8Array;
 43→  teeKeys?: TeeKeys;
 44→};
 45→
 46→/**
 47→ * Internal state for the bin (replaces useBinStore).
 48→ */
 49→export type BinState = {
 50→  entries: BinEntry[];
 51→  sequenceNumber: number;
 52→  ipnsName: string;
 53→};
 54→
 55→// ---------------------------------------------------------------------------
 56→// Internal helpers: load / save bin metadata
 57→// ---------------------------------------------------------------------------
 58→
 59→/**
 60→ * Load and decrypt bin metadata from IPNS.
 61→ */
 62→async function loadBinMetadataInternal(params: {
 63→  userPrivateKey: Uint8Array;
 64→  ctx: SdkContext;
 65→}): Promise<{
 66→  metadata: RecycleBinMetadata;
 67→  ipnsName: string;
 68→  sequenceNumber: bigint;
 69→} | null> {
 70→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 71→  const resolved = await sdkCore.resolveIpnsRecord(binIpns.ipnsName);
 72→
 73→  if (!resolved) return null;
 74→
 75→  const encryptedBytes = await sdkCore.fetchFromIpfs(params.ctx, resolved.cid);
 76→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 77→
 78→  return {
 79→    metadata,
 80→    ipnsName: binIpns.ipnsName,
 81→    sequenceNumber: resolved.sequenceNumber,
 82→  };
 83→}
 84→
 85→/**
 86→ * Encrypt and publish bin metadata to IPNS.
 87→ */
 88→async function saveBinMetadata(params: {
 89→  metadata: RecycleBinMetadata;
 90→  binCtx: BinOperationContext;
 91→}): Promise<void> {
 92→  const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
 93→
 94→  // Encrypt metadata with user's public key (ECIES)
 95→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.binCtx.userPublicKey);
 96→
 97→  // Pin to IPFS
 98→  const { cid } = await sdkCore.addToIpfs(params.binCtx.ctx, encryptedBytes);
 99→
100→  // TEE enrollment (optional)
101→  let encryptedIpnsKey: string | undefined;
102→  let keyEpoch: number | undefined;
103→
104→  if (params.binCtx.teeKeys?.currentPublicKey) {
105→    try {
106→      const teePublicKey = hexToBytes(params.binCtx.teeKeys.currentPublicKey);
107→      const wrappedKey = await wrapKey(binIpns.privateKey, teePublicKey);
108→      encryptedIpnsKey = bytesToHex(wrappedKey);
109→      keyEpoch = params.binCtx.teeKeys.currentEpoch;
110→    } catch {
111→      // TEE enrollment failure is non-blocking
112→    }
113→  }
114→
115→  // Publish IPNS record
116→  await sdkCore.createAndPublishIpnsRecord({
117→    ipnsPrivateKey: binIpns.privateKey,
118→    ipnsName: binIpns.ipnsName,
119→    metadataCid: cid,
120→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
121→    encryptedIpnsPrivateKey: encryptedIpnsKey,
122→    keyEpoch,
123→  });
124→}
125→
126→// ---------------------------------------------------------------------------
127→// Public API
128→// ---------------------------------------------------------------------------
129→
130→/**
131→ * Load the recycle bin metadata from IPNS.
132→ *
133→ * If no bin IPNS record exists yet (first login / never deleted anything),
134→ * returns an empty BinState so that deleteToBin can create the first record.
135→ * The old bin service handled this by creating in-memory-only empty state;
136→ * the SDK must do the same to avoid "Bin not loaded" errors on first delete.
137→ *
138→ * @returns Current bin state (never null — empty state if no record exists)
139→ */
140→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
141→  const loaded = await loadBinMetadataInternal({
142→    userPrivateKey: params.binCtx.userPrivateKey,
143→    ctx: params.binCtx.ctx,
144→  });
145→
146→  if (!loaded) {
147→    // No bin IPNS record exists yet — return empty state.
148→    // The first addToBin call will create the IPNS record.
149→    const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
150→    return {
151→      entries: [],
152→      sequenceNumber: 0,
153→      ipnsName: binIpns.ipnsName,
154→    };
155→  }
156→
157→  return {
158→    entries: loaded.metadata.entries,
159→    sequenceNumber: loaded.metadata.sequenceNumber,
160→    ipnsName: loaded.ipnsName,
161→  };
162→}
163→
164→/**
165→ * Add item to recycle bin.
166→ *
167→ * Removes the item from the folder metadata (via deleteFromFolder),
168→ * creates a BinEntry, appends to bin metadata, and publishes both.
169→ *
170→ * @returns The removed item from the folder
171→ */
172→export async function addToBin(params: {
173→  folderIpnsName: string;
174→  childId: string;
175→  parentPath: string;
176→  folderTree: FolderTree;
177→  binState: BinState;
178→  binCtx: BinOperationContext;
179→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
180→  const folder = params.folderTree.get(params.folderIpnsName);
181→  if (!folder) throw new Error('Folder not loaded');
182→
183→  // 1. Remove item from folder metadata
184→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
185→    children: folder.children,
186→    childId: params.childId,
187→  });
188→
189→  // 2. Publish updated folder metadata
190→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
191→    children: updatedChildren,
192→    folderKey: folder.folderKey,
193→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
194→    ipnsName: params.folderIpnsName,
195→    sequenceNumber: folder.sequenceNumber,
196→    ctx: params.binCtx.ctx,
197→  });
198→
199→  // 3. Update folder state
200→  folder.children = updatedChildren;
201→  folder.sequenceNumber = newSequenceNumber;
202→  folder.lastLoadedAt = Date.now();
203→  params.folderTree.set(params.folderIpnsName, folder);
204→
205→  // 4. Build bin entry
206→  const isFile = removedItem.type === 'file';
207→  const entry: BinEntry = {
208→    id: crypto.randomUUID(),
209→    itemType: isFile ? 'file' : 'folder',
210→    name: removedItem.name,
211→    originalParentIpnsName: params.folderIpnsName,
212→    originalPath: params.parentPath,
213→    deletedAt: Date.now(),
214→    size: 0,
215→    mimeType: '',
216→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
217→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
218→  };
219→
220→  // 5. Update bin metadata and publish
221→  const updatedEntries = [...params.binState.entries, entry];
222→  const newBinSeq = params.binState.sequenceNumber + 1;
223→
224→  const metadata: RecycleBinMetadata = {
225→    version: BIN_METADATA_VERSION,
226→    sequenceNumber: newBinSeq,
227→    entries: updatedEntries,
228→  };
229→
230→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
231→
232→  const updatedBinState: BinState = {
233→    entries: updatedEntries,
234→    sequenceNumber: newBinSeq,
235→    ipnsName: params.binState.ipnsName,
236→  };
237→
238→  return { removedItem, updatedBinState };
239→}
