241→/**
242→ * Restore an item from the recycle bin back to a folder.
243→ *
244→ * Removes the entry from bin metadata, adds the preserved FolderChild
245→ * back to the target folder's children, and publishes both.
246→ */
247→export async function restoreFromBin(params: {
248→  entryId: string;
249→  targetFolderIpnsName: string;
250→  folderTree: FolderTree;
251→  binState: BinState;
252→  binCtx: BinOperationContext;
253→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
254→  // 1. Find the bin entry
255→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
256→  if (!entry) throw new Error('Bin entry not found');
257→
258→  // 2. Get the FolderChild to restore
259→  let child: FolderChild;
260→  if (entry.itemType === 'file' && entry.filePointer) {
261→    child = { ...entry.filePointer, modifiedAt: Date.now() };
262→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
263→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
264→  } else {
265→    throw new Error('Bin entry has no stored item reference');
266→  }
267→
268→  // 3. Add child back to target folder
269→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
270→  if (!targetFolder) throw new Error('Target folder not loaded');
271→
272→  // Handle name collisions
273→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
274→  if (existingNames.has(child.name)) {
275→    let newName = `${child.name} (restored)`;
276→    let counter = 2;
277→    while (existingNames.has(newName)) {
278→      newName = `${child.name} (restored ${counter})`;
279→      counter++;
280→    }
281→    child = { ...child, name: newName };
282→  }
283→
284→  const updatedFolderChildren = [...targetFolder.children, child];
285→
286→  // 4. Publish updated folder metadata
287→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
288→    children: updatedFolderChildren,
289→    folderKey: targetFolder.folderKey,
290→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
291→    ipnsName: params.targetFolderIpnsName,
292→    sequenceNumber: targetFolder.sequenceNumber,
293→    ctx: params.binCtx.ctx,
294→  });
295→
296→  // 5. Update folder state
297→  targetFolder.children = updatedFolderChildren;
298→  targetFolder.sequenceNumber = newSequenceNumber;
299→  targetFolder.lastLoadedAt = Date.now();
300→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
301→
302→  // 6. Remove entry from bin and publish
303→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
304→  const newBinSeq = params.binState.sequenceNumber + 1;
305→
306→  const metadata: RecycleBinMetadata = {
307→    version: BIN_METADATA_VERSION,
308→    sequenceNumber: newBinSeq,
309→    entries: remainingEntries,
310→  };
311→
312→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
313→
314→  const updatedBinState: BinState = {
315→    entries: remainingEntries,
316→    sequenceNumber: newBinSeq,
317→    ipnsName: params.binState.ipnsName,
318→  };
319→
320→  return { restoredItem: child, updatedBinState };
321→}
