 1→import { useCallback, useState } from 'react';
 2→import { deleteFile, deleteFiles } from '../services/delete.service';
 3→// Note: delete.service.ts handles IPFS unpin + quota update.
 4→// SDK's permanentDelete handles bin-level deletion (different concern).
 5→// Both services are needed: delete.service for CID cleanup, SDK for bin operations.
