 7→export function useFileDelete() {
 8→  const [isDeleting, setIsDeleting] = useState(false);
 9→  const [error, setError] = useState<string | null>(null);
10→
11→  const deleteSingle = useCallback(async (cid: string, sizeBytes: number): Promise<void> => {
12→    setIsDeleting(true);
13→    setError(null);
14→
15→    try {
16→      await deleteFile(cid, sizeBytes);
17→    } catch (err) {
18→      const message = (err as Error).message || 'Delete failed';
19→      setError(message);
20→      throw err;
21→    } finally {
22→      setIsDeleting(false);
23→    }
24→  }, []);
25→
26→  const deleteMultiple = useCallback(
27→    async (
28→      files: Array<{ cid: string; size: number }>
29→    ): Promise<{ succeeded: string[]; failed: string[] }> => {
30→      setIsDeleting(true);
31→      setError(null);
32→
33→      try {
34→        const result = await deleteFiles(files);
35→        if (result.failed.length > 0) {
36→          setError(`Failed to delete ${result.failed.length} file(s)`);
37→        }
38→        return result;
39→      } finally {
40→        setIsDeleting(false);
41→      }
42→    },
43→    []
44→  );
45→
46→  return {
47→    isDeleting,
48→    error,
49→    deleteFile: deleteSingle,
50→    deleteFiles: deleteMultiple,
51→    clearError: () => setError(null),
52→  };
53→}
