43→export const useAuthStore = create<AuthState>((set, get) => ({
44→  // State - stored in memory only, NOT localStorage (XSS prevention)
45→  accessToken: null,
46→  isAuthenticated: false,
47→  lastAuthMethod: null,
48→  userEmail: null,
49→  teeKeys: null,
50→
51→  /** User's vault keypair (memory-only) */
