61→  setLastAuthMethod: (method) => set({ lastAuthMethod: method }),
62→  setUserEmail: (email) => set({ userEmail: email }),
63→  setTeeKeys: (keys) => set({ teeKeys: keys }),
64→
65→  /** Store vault keypair from Core Kit TSS export */
