83→    set({
84→      accessToken: null,
85→      isAuthenticated: false,
86→      userEmail: null,
87→      teeKeys: null,
88→      vaultKeypair: null,
89→      pendingCipherboxJwt: null,
90→      pendingAuthMethod: null,
91→    });
92→  },
93→}));
