115→    @Body() body: DesktopRefreshDto,
116→    @Res({ passthrough: true }) res: Response
117→  ): Promise<TokenResponseDto> {
118→    const isDesktop = req.headers['x-client-type'] === 'desktop';
119→
120→    let refreshToken: string | undefined;
121→
122→    if (isDesktop) {
123→      // Desktop clients: read refresh token from request body
124→      refreshToken = body?.refreshToken;
