140→        refreshToken: result.refreshToken,
141→        email: result.email,
142→      };
143→    }
144→
145→    // Web clients: set new refresh token in HTTP-only cookie (rotation)
146→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
147→
148→    return {
149→      accessToken: result.accessToken,
150→      email: result.email,
151→    };
