 77→      let publishOutcome = 'success';
 78→      try {
 79→        await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
 80→      } catch (error) {
 81→        result = 'delegated_error';
 82→        publishOutcome = 'error';
 83→        this.logger.warn(
 84→          `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 85→        );
 86→      } finally {
 87→        const publishElapsed = Number(process.hrtime.bigint() - publishStart) / 1e9;
 88→        this.metricsService.ipnsPublishDuration.observe(
 89→          { outcome: publishOutcome },
 90→          publishElapsed
 91→        );
 92→      }
 93→
 94→      return {
 95→        success: true,
 96→        ipnsName: dto.ipnsName,
 97→        sequenceNumber: folder.sequenceNumber,
 98→      };
 99→    } catch (error) {
100→      result = 'error';
101→      throw error;
102→    } finally {
103→      endTimer({ result });
104→    }
105→  }
