24→export function clearAllUserStores(): void {
25→  // 0. Destroy SDK client first (clears key caches, event subscriptions)
26→  destroySdkClient();
27→
28→  // 1. Clear stores with crypto key material first
29→  useFolderStore.getState().clearFolders();
30→  useVaultStore.getState().clearVaultKeys();
31→
32→  // 2. Clear remaining user-scoped stores
33→  useSyncStore.getState().reset();
34→  useDeviceRegistryStore.getState().clearRegistry();
35→  useBinStore.getState().clearBin();
36→  useShareStore.getState().clearShares();
37→  useQuotaStore.getState().reset();
38→  useMfaStore.getState().reset();
39→  useNotificationStore.getState().clearNotifications();
40→  clearFileSizeCache();
41→
42→  // 3. Clear auth state last (zeros keypair memory, sets isAuthenticated=false)
43→  useAuthStore.getState().logout();
44→}
