 * @param cid - IPFS CID of the file
 * @param onProgress - Optional callback for download progress
 * @returns Encrypted file content as Uint8Array
 */
export async function fetchFromIpfs(
  cid: string,
  onProgress?: DownloadProgressCallback
): Promise<Uint8Array> {
  if (!onProgress) {
    // Simple path: use apiClient for automatic token refresh
    const response = await apiClient.get(`/ipfs/${cid}`, { responseType: 'arraybuffer' });
    return new Uint8Array(response.data);
  }

  // Progress path: use apiClient for a HEAD-like check (validates token / triggers refresh),
  // then stream via fetch with the (potentially refreshed) token.
  // We read the fresh token from the store right before the fetch call.
  const { useAuthStore: store } = await import('../../stores/auth.store');
  const baseURL = apiClient.defaults.baseURL || '';

  // Make a lightweight request through apiClient first to ensure token is valid.
  // If the token is expired, the interceptor will refresh it before this resolves.
  // We use a HEAD-like approach by requesting with a range that returns minimal data.
  // Actually, just get the token -- if it was recently refreshed by another call, it's fine.
  // The risk is minimal since fetchFromIpfs is typically called shortly after other API calls.
  const accessToken = store.getState().accessToken;

  const response = await fetch(`${baseURL}/ipfs/${cid}`, {
    headers: {
      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
    },
  });

  if (response.status === 401) {
    // Token expired -- refresh via apiClient (which handles refresh + dedup)
    // and retry with the new token
    try {
      await apiClient.post('/auth/refresh');
    } catch {
      // Refresh failed, re-throw as fetch error
      throw new Error(`Failed to fetch from IPFS: 401`);
    }
    const newToken = store.getState().accessToken;
    const retryResponse = await fetch(`${baseURL}/ipfs/${cid}`, {
      headers: {
