/**
 * Shared token refresh logic used by both API client systems:
 * - apps/web/src/api/custom-instance.ts (orval-generated, fetch-based)
 * - apps/web/src/lib/api/client.ts (hand-written, axios-based)
 *
 * Having a single shared refresh promise prevents the race condition where
 * both systems detect a 401 simultaneously and fire duplicate refresh requests
 * (which would fail due to refresh token rotation revoking the first token).
 */
import { useAuthStore } from '../stores/auth.store';
import { clearAllUserStores } from './clear-user-stores';

// Shared refresh promise eliminates race condition where multiple concurrent
// 401 responses each trigger their own POST /auth/refresh.
// The promise is assigned synchronously before any await,
// so all concurrent 401 handlers see it immediately and share the same refresh.
let refreshPromise: Promise<string> | null = null;

/**
 * Get the API base URL (same logic as both client systems).
 */
function getBaseUrl(): string {
  return (
    import.meta.env.VITE_API_URL ||
    (typeof window !== 'undefined' ? `${window.location.origin}/api` : '/api')
  );
}

/**
 * Attempt to refresh the access token using the HTTP-only refresh token cookie.
 * Returns the new access token on success, throws on failure.
 *
 * All concurrent callers across BOTH API client systems share the same
 * in-flight promise, preventing duplicate refresh requests.
 */
export function refreshAccessToken(): Promise<string> {
  if (refreshPromise) return refreshPromise;

  const baseUrl = getBaseUrl();

  refreshPromise = fetch(`${baseUrl}/auth/refresh`, {
    method: 'POST',
    credentials: 'include', // Send HTTP-only refresh token cookie
    headers: { 'Content-Type': 'application/json' },
  })
    .then(async (res) => {
      if (!res.ok) {
        throw new Error(`Refresh failed: ${res.status}`);
      }
      const body = await res.json();
      const { accessToken } = body as { accessToken: string };

      // Update Zustand store so subsequent requests use the new token
      const store = useAuthStore.getState();
      store.setAccessToken(accessToken);
      store.setAuthenticated();

      return accessToken;
    })
    .catch((err) => {
      // [SECURITY: HIGH-03] Clear all stores including crypto keys on refresh failure
      clearAllUserStores();
      throw err;
    })
    .finally(() => {
      refreshPromise = null;
    });

  return refreshPromise;
}

