  9→/**
 10→ * Execute a fetch request with the given config and access token.
 11→ */
 12→async function executeFetch(
 13→  config: CustomInstanceConfig,
 14→  accessToken: string | null
 15→): Promise<Response> {
 16→  const { url, method, params, data, headers, signal, responseType = 'json' } = config;
 17→
 18→  const queryString = params
 19→    ? '?' +
 20→      new URLSearchParams(
 21→        Object.entries(params)
 22→          .filter(([, v]) => v !== undefined)
 23→          .map(([k, v]) => [k, String(v)])
 24→      ).toString()
 25→    : '';
 26→
 27→  return fetch(`${BASE_URL}${url}${queryString}`, {
 28→    method,
 29→    credentials: 'include', // Always send cookies (needed for refresh token)
 30→    headers: {
 31→      // Only set Content-Type for JSON requests with body
 32→      ...(data && responseType === 'json' ? { 'Content-Type': 'application/json' } : {}),
 33→      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
 34→      ...headers,
 35→    },
 36→    body: data ? JSON.stringify(data) : undefined,
 37→    signal,
 38→  });
 39→}
 40→
 41→/**
 42→ * Parse a fetch response according to the expected response type.
 43→ */
 44→async function parseResponse<T>(
 45→  response: Response,
 46→  responseType: 'json' | 'blob' | 'text' = 'json'
 47→): Promise<T> {
 48→  if (responseType === 'blob') {
 49→    return response.blob() as Promise<T>;
 50→  } else if (responseType === 'text') {
 51→    return response.text() as Promise<T>;
 52→  }
 53→  // Responses with no body (204 No Content, 201 with void return, etc.)
 54→  // Read as text first to avoid JSON parse error on empty bodies
 55→  const text = await response.text();
 56→  if (!text.trim()) {
 57→    return undefined as T;
 58→  }
 59→  return JSON.parse(text);
 60→}
 61→
 62→type CustomInstanceConfig = {
 63→  url: string;
 64→  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
 65→  params?: Record<string, string | number | boolean | undefined>;
 66→  data?: unknown;
 67→  headers?: Record<string, string>;
 68→  signal?: AbortSignal;
 69→  responseType?: 'json' | 'blob' | 'text';
 70→};
 71→
 72→export const customInstance = async <T>(config: CustomInstanceConfig): Promise<T> => {
 73→  const accessToken = useAuthStore.getState().accessToken;
 74→
 75→  const response = await executeFetch(config, accessToken);
 76→
 77→  if (response.ok) {
 78→    return parseResponse<T>(response, config.responseType);
 79→  }
 80→
 81→  // Handle 401: attempt token refresh and retry (once)
 82→  // Don't retry the refresh endpoint itself to avoid infinite loops
 83→  const isRefreshRequest = config.url.includes('/auth/refresh');
 84→  if (response.status === 401 && !isRefreshRequest) {
 85→    try {
