 98→      // (clearAllUserStores already called by refreshAccessToken on failure)
 99→      const err = new Error(`HTTP error! status: 401`);
100→      (err as Error & { status: number }).status = 401;
101→      throw err;
102→    }
103→  }
104→
105→  const err = new Error(`HTTP error! status: ${response.status}`);
106→  (err as Error & { status: number }).status = response.status;
107→  throw err;
108→};
