 1→/**
 2→ * Shared token refresh logic used by both API client systems:
 3→ * - apps/web/src/api/custom-instance.ts (orval-generated, fetch-based)
 4→ * - apps/web/src/lib/api/client.ts (hand-written, axios-based)
 5→ *
 6→ * Having a single shared refresh promise prevents the race condition where
 7→ * both systems detect a 401 simultaneously and fire duplicate refresh requests
 8→ * (which would fail due to refresh token rotation revoking the first token).
 9→ */
10→import { useAuthStore } from '../stores/auth.store';
11→import { clearAllUserStores } from './clear-user-stores';
12→
13→// Shared refresh promise eliminates race condition where multiple concurrent
14→// 401 responses each trigger their own POST /auth/refresh.
15→// The promise is assigned synchronously before any await,
16→// so all concurrent 401 handlers see it immediately and share the same refresh.
17→let refreshPromise: Promise<string> | null = null;
18→
19→/**
20→ * Get the API base URL (same logic as both client systems).
21→ */
22→function getBaseUrl(): string {
23→  return (
24→    import.meta.env.VITE_API_URL ||
25→    (typeof window !== 'undefined' ? `${window.location.origin}/api` : '/api')
26→  );
27→}
28→
29→/**
30→ * Attempt to refresh the access token using the HTTP-only refresh token cookie.
31→ * Returns the new access token on success, throws on failure.
32→ *
33→ * All concurrent callers across BOTH API client systems share the same
34→ * in-flight promise, preventing duplicate refresh requests.
35→ */
36→export function refreshAccessToken(): Promise<string> {
37→  if (refreshPromise) return refreshPromise;
38→
39→  const baseUrl = getBaseUrl();
40→
41→  refreshPromise = fetch(`${baseUrl}/auth/refresh`, {
42→    method: 'POST',
43→    credentials: 'include', // Send HTTP-only refresh token cookie
44→    headers: { 'Content-Type': 'application/json' },
45→  })
46→    .then(async (res) => {
47→      if (!res.ok) {
48→        throw new Error(`Refresh failed: ${res.status}`);
49→      }
50→      const body = await res.json();
51→      const { accessToken } = body as { accessToken: string };
52→
53→      // Update Zustand store so subsequent requests use the new token
54→      const store = useAuthStore.getState();
55→      store.setAccessToken(accessToken);
56→      store.setAuthenticated();
57→
58→      return accessToken;
59→    })
60→    .catch((err) => {
61→      // [SECURITY: HIGH-03] Clear all stores including crypto keys on refresh failure
62→      clearAllUserStores();
63→      throw err;
64→    })
65→    .finally(() => {
66→      refreshPromise = null;
67→    });
68→
69→  return refreshPromise;
70→}
71→

 1→import axios from 'axios';
 2→import { useAuthStore } from '../../stores/auth.store';
 3→import { refreshAccessToken } from '../token-refresh';
 4→
 5→export const apiClient = axios.create({
 6→  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:3000',
 7→  withCredentials: true, // For HTTP-only refresh token cookie
 8→});
 9→
10→// Request interceptor: Add access token to headers
11→apiClient.interceptors.request.use((config) => {
12→  const accessToken = useAuthStore.getState().accessToken;
13→  if (accessToken) {
14→    config.headers.Authorization = `Bearer ${accessToken}`;
15→  }
16→  return config;
17→});
18→
19→// Response interceptor: Handle 401 and token refresh
20→// Uses shared refreshAccessToken() from lib/token-refresh.ts so that
21→// concurrent 401s from BOTH the axios apiClient and the fetch-based
22→// custom-instance share a single refresh request.
23→apiClient.interceptors.response.use(
24→  (response) => response,
25→  async (error) => {
26→    const originalRequest = error.config;
27→
28→    // Don't retry refresh endpoint to avoid infinite loop
29→    const isRefreshRequest = originalRequest?.url?.includes('/auth/refresh');
30→
31→    // Only handle 401 errors, and only retry once (but never retry refresh endpoint)
32→    if (error.response?.status === 401 && !originalRequest._retry && !isRefreshRequest) {
33→      originalRequest._retry = true;
34→
35→      try {
36→        const token = await refreshAccessToken();
37→        originalRequest.headers.Authorization = `Bearer ${token}`;
38→        return apiClient(originalRequest);
39→      } catch {
40→        // refreshAccessToken already called clearAllUserStores on failure
41→        throw error;
42→      }
43→    }
44→
45→    throw error;
46→  }
47→);
