 1→import type { AxiosProgressEvent, CancelToken } from 'axios';
 2→import { apiClient } from './client';
 3→
 4→export type AddResponse = { cid: string; size: number; recorded: boolean };
 5→
 6→export type DownloadProgressCallback = (loaded: number, total: number) => void;
 7→
 8→/**
 9→ * Upload encrypted file to IPFS via backend relay.
10→ * Uses apiClient (which has 401 token-refresh interceptor) with progress tracking.
11→ */
12→export async function addToIpfs(
13→  encryptedFile: Blob,
14→  onProgress?: (percent: number) => void,
15→  cancelToken?: CancelToken
16→): Promise<AddResponse> {
17→  const formData = new FormData();
18→  formData.append('file', encryptedFile);
19→
20→  const response = await apiClient.post<AddResponse>('/ipfs/upload', formData, {
21→    // Content-Type is set automatically by axios for FormData
22→    onUploadProgress: (event: AxiosProgressEvent) => {
23→      if (event.total && onProgress) {
24→        const percent = Math.round((event.loaded * 100) / event.total);
25→        onProgress(percent);
26→      }
27→    },
28→    cancelToken,
29→  });
30→
31→  return response.data;
32→}
33→
34→/**
35→ * Unpin file from IPFS via backend relay.
36→ */
37→export async function unpinFromIpfs(cid: string): Promise<void> {
38→  await apiClient.post('/ipfs/unpin', { cid });
39→}
40→
41→/**
42→ * Fetch encrypted file from IPFS via the API proxy.
43→ * Supports progress tracking for larger files.
44→ *
45→ * Uses apiClient (with 401 token-refresh interceptor) for all requests.
46→ * When progress tracking is needed, uses axios onDownloadProgress.
47→ *
48→ * @param cid - IPFS CID of the file
49→ * @param onProgress - Optional callback for download progress
50→ * @returns Encrypted file content as Uint8Array
51→ */
52→export async function fetchFromIpfs(
53→  cid: string,
54→  onProgress?: DownloadProgressCallback
55→): Promise<Uint8Array> {
56→  const response = await apiClient.get(`/ipfs/${cid}`, {
57→    responseType: 'arraybuffer',
58→    ...(onProgress && {
59→      onDownloadProgress: (event: AxiosProgressEvent) => {
60→        if (event.total) {
61→          onProgress(event.loaded, event.total);
62→        }
63→      },
64→    }),
65→  });
66→  return new Uint8Array(response.data);
67→}

