import { useAuthStore } from '../stores/auth.store';
import { refreshAccessToken } from '../lib/token-refresh';

// Use VITE_API_URL if set, otherwise default to same-origin /api path for deployed environments
const BASE_URL =
  import.meta.env.VITE_API_URL ||
  (typeof window !== 'undefined' ? `${window.location.origin}/api` : '/api');

/**
 * Execute a fetch request with the given config and access token.
 */
async function executeFetch(
  config: CustomInstanceConfig,
  accessToken: string | null
): Promise<Response> {
  const { url, method, params, data, headers, signal, responseType = 'json' } = config;

  const queryString = params
    ? '?' +
      new URLSearchParams(
        Object.entries(params)
          .filter(([, v]) => v !== undefined)
          .map(([k, v]) => [k, String(v)])
      ).toString()
    : '';

  return fetch(`${BASE_URL}${url}${queryString}`, {
    method,
    credentials: 'include', // Always send cookies (needed for refresh token)
    headers: {
      // Only set Content-Type for JSON requests with body
      ...(data && responseType === 'json' ? { 'Content-Type': 'application/json' } : {}),
      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
      ...headers,
    },
    body: data ? JSON.stringify(data) : undefined,
    signal,
  });
}

/**
 * Parse a fetch response according to the expected response type.
 */
async function parseResponse<T>(
  response: Response,
  responseType: 'json' | 'blob' | 'text' = 'json'
): Promise<T> {
  if (responseType === 'blob') {
    return response.blob() as Promise<T>;
  } else if (responseType === 'text') {
    return response.text() as Promise<T>;
  }
  // Responses with no body (204 No Content, 201 with void return, etc.)
  // Read as text first to avoid JSON parse error on empty bodies
  const text = await response.text();
  if (!text.trim()) {
    return undefined as T;
  }
  return JSON.parse(text);
}

type CustomInstanceConfig = {
  url: string;
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  params?: Record<string, string | number | boolean | undefined>;
  data?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  responseType?: 'json' | 'blob' | 'text';
};

export const customInstance = async <T>(config: CustomInstanceConfig): Promise<T> => {
  const accessToken = useAuthStore.getState().accessToken;

  const response = await executeFetch(config, accessToken);

  if (response.ok) {
    return parseResponse<T>(response, config.responseType);
  }

  // Handle 401: attempt token refresh and retry (once)
  // Don't retry the refresh endpoint itself to avoid infinite loops
  const isRefreshRequest = config.url.includes('/auth/refresh');
  if (response.status === 401 && !isRefreshRequest) {
    try {
      const newToken = await refreshAccessToken();
      const retryResponse = await executeFetch(config, newToken);

      if (!retryResponse.ok) {
        const err = new Error(`HTTP error! status: ${retryResponse.status}`);
        (err as Error & { status: number }).status = retryResponse.status;
        throw err;
      }

      return parseResponse<T>(retryResponse, config.responseType);
    } catch {
      // Refresh failed -- throw the original 401 error
      // (clearAllUserStores already called by refreshAccessToken on failure)
      const err = new Error(`HTTP error! status: 401`);
      (err as Error & { status: number }).status = 401;
      throw err;
    }
  }

  const err = new Error(`HTTP error! status: ${response.status}`);
  (err as Error & { status: number }).status = response.status;
  throw err;
};

export default customInstance;

