import axios from 'axios';
import { useAuthStore } from '../../stores/auth.store';
import { refreshAccessToken } from '../token-refresh';

export const apiClient = axios.create({
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:3000',
  withCredentials: true, // For HTTP-only refresh token cookie
});

// Request interceptor: Add access token to headers
apiClient.interceptors.request.use((config) => {
  const accessToken = useAuthStore.getState().accessToken;
  if (accessToken) {
    config.headers.Authorization = `Bearer ${accessToken}`;
  }
  return config;
});

// Response interceptor: Handle 401 and token refresh
// Uses shared refreshAccessToken() from lib/token-refresh.ts so that
// concurrent 401s from BOTH the axios apiClient and the fetch-based
// custom-instance share a single refresh request.
apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    // Don't retry refresh endpoint to avoid infinite loop
    const isRefreshRequest = originalRequest?.url?.includes('/auth/refresh');

    // Only handle 401 errors, and only retry once (but never retry refresh endpoint)
    if (error.response?.status === 401 && !originalRequest._retry && !isRefreshRequest) {
      originalRequest._retry = true;

      try {
        const token = await refreshAccessToken();
        originalRequest.headers.Authorization = `Bearer ${token}`;
        return apiClient(originalRequest);
      } catch {
        // refreshAccessToken already called clearAllUserStores on failure
        throw error;
      }
    }

    throw error;
  }
);

