  return customInstance<VaultResponseDto>({
    url: `/vault/init`,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    data: initVaultDto,
    signal,
  });
};

export const getVaultControllerInitializeVaultMutationOptions = <
  TError = void,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof vaultControllerInitializeVault>>,
    TError,
    { data: InitVaultDto },
    TContext
  >;
}): UseMutationOptions<
  Awaited<ReturnType<typeof vaultControllerInitializeVault>>,
  TError,
  { data: InitVaultDto },
  TContext
> => {
  const mutationKey = ['vaultControllerInitializeVault'];
  const { mutation: mutationOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey } };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof vaultControllerInitializeVault>>,
    { data: InitVaultDto }
  > = (props) => {
    const { data } = props ?? {};

    return vaultControllerInitializeVault(data);

