  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import { useVaultStore } from '../stores/vault.store';
 10→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 11→import { clearAllUserStores } from '../lib/clear-user-stores';
 12→import { initSdkClient } from '../lib/sdk-provider';
 13→import { setApiClientConfig } from '@cipherbox/api-client';
 14→import { initializeVault, encryptVaultKeys, decryptVaultKeys } from '@cipherbox/core';
 15→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 16→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 17→import { detectDeviceInfo } from '../lib/device/info';
 18→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 19→import { initializeBin } from '../services/bin.service';
 20→import { useBinStore } from '../stores/bin.store';
 21→import { vaultControllerGetConfig } from '../api/vault/vault';
 22→
 23→export function useAuth() {
 24→  const navigate = useNavigate();
 25→  const {
 26→    isLoggedIn: coreKitLoggedIn,
 27→    isInitialized: coreKitInitialized,
 28→    isRequiredShare,
 29→    loginWithGoogle: coreKitLoginGoogle,
 30→    loginWithEmailOtp: coreKitLoginEmail,
 31→    loginWithWallet: coreKitLoginWallet,
 32→    getVaultKeypair,
 33→    getPublicKeyHex,
 34→    logout: coreKitLogout,
 35→  } = useCoreKitAuth();
 36→  const { syncStatus } = useCoreKit();
 37→  const {
 38→    accessToken,
 39→    isAuthenticated,
 40→    lastAuthMethod,
 41→    userEmail,
 42→    setAccessToken,
 43→    setAuthenticated,
 44→    setLastAuthMethod,
 45→    setUserEmail,
 46→    setVaultKeypair,
 47→  } = useAuthStore();
 48→
 49→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 50→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 51→  const restoringRef = useRef(false);
 52→
 53→  // Stable refs for functions used in the session restoration effect.
 54→  // This prevents the effect from re-firing when function references change.
 55→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 56→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 57→
 58→  // Pending auth state for REQUIRED_SHARE flow.
 59→  // Stored in Zustand (not useState) so the state is shared across all
 60→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 61→  // via its own useAuth() call.
 62→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 63→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 64→
 65→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 66→
 67→  // Get vault store actions
 68→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 69→
 70→  /**
 71→   * Initialize vault for new users or load existing vault keys.
 72→   * Called after successful backend authentication.
 73→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 74→   */
 75→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 76→    // Get user's secp256k1 keypair from Core Kit TSS export
 77→    const userKeypair = await getVaultKeypair();
 78→
 79→    if (!userKeypair) {
 80→      throw new Error('Failed to get vault keypair from Core Kit');
 81→    }
 82→
 83→    // Store keypair in auth store for crypto operations
 84→    setVaultKeypair(userKeypair);
 85→
 86→    try {
 87→      // Try to fetch existing vault
 88→      const existingVault = await vaultApi.getVault();
 89→
 90→      // Store TEE keys if available
 91→      if (existingVault.teeKeys) {
 92→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 93→      }
 94→
 95→      // Vault exists - decrypt keys and load into store
 96→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 97→      const decryptedVault = await decryptVaultKeys(
 98→        {
 99→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
100→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
101→        },
102→        userKeypair.privateKey
103→      );
104→
105→      setVaultKeys({
106→        rootFolderKey: decryptedVault.rootFolderKey,
107→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
108→        rootIpnsName: existingVault.rootIpnsName,
109→        vaultId: existingVault.id,
110→      });
111→    } catch (error) {
112→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
113→
114→      if (is404) {
115→        // New user - initialize vault
116→        console.log(
117→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
118→        );
119→        const newVault = await initializeVault(userKeypair.privateKey);
120→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
121→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
122→
123→        const storedVault = await vaultApi.initVault({
124→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
125→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
126→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
127→          rootIpnsName,
128→        });
129→
130→        if (storedVault.teeKeys) {
131→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
132→        }
133→
134→        setVaultKeys({
135→          rootFolderKey: newVault.rootFolderKey,
136→          rootIpnsKeypair: newVault.rootIpnsKeypair,
137→          rootIpnsName,
138→          vaultId: storedVault.id,
139→          isNewVault: true,
140→        });
141→      } else {
142→        console.error('[useAuth] Failed to load vault:', error);
143→        throw error;
144→      }
145→    }
146→
147→    // Initialize SDK client with decrypted vault keys
148→    const vaultState = useVaultStore.getState();
149→    const authState = useAuthStore.getState();
150→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
151→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
152→      const getAccessToken = async () => {
153→        const state = useAuthStore.getState();
154→        return state.accessToken || '';
155→      };
156→
157→      // Configure @cipherbox/api-client for SDK-core IPNS operations
158→      setApiClientConfig({ baseUrl: apiUrl, getAccessToken });
159→
160→      const sdkClient = initSdkClient({
161→        apiUrl,
162→        getAccessToken,
163→        vaultKeypair: {
164→          publicKey: userKeypair.publicKey,
165→          privateKey: userKeypair.privateKey,
166→        },
167→        rootIpnsName: vaultState.rootIpnsName,
168→        rootFolderKey: vaultState.rootFolderKey,
169→        teeKeys: authState.teeKeys ?? undefined,
170→        shareCallbacks: {
171→          getCoveringShares: async (folderIpnsName: string) => {
172→            const { findCoveringShares } = await import('../services/share.service');
173→            const folders = useFolderStore.getState().folders;
174→            // Find the folder ID from IPNS name for ancestor traversal
175→            const folderId =
176→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
177→            return findCoveringShares(folderIpnsName, folders, folderId);
178→          },
179→          addShareKeys: async (shareId, keys) => {
180→            const { addShareKeys } = await import('../services/share.service');
181→            await addShareKeys(shareId, keys);
182→          },
183→        },
184→      });
185→
186→      // Subscribe folder store to SDK events
187→      useFolderStore.getState().subscribeToSdk(sdkClient);
188→
189→      // Subscribe bin store to SDK events
190→      useBinStore.getState().subscribeToSdk(sdkClient);
191→    }
192→
193→    // Non-blocking device registry initialization (fire-and-forget)
194→    // Placed after vault load so registry failures never block login
195→    void (async () => {
196→      try {
197→        const deviceKeypair = await getOrCreateDeviceIdentity({
198→          mode: 'persisted',
199→          vaultPrivateKey: userKeypair.privateKey,
200→        });
201→        const deviceInfo = detectDeviceInfo();
202→        const result = await initializeOrSyncRegistry({
203→          userPrivateKey: userKeypair.privateKey,
204→          userPublicKey: userKeypair.publicKey,
205→          deviceKeypair,
206→          deviceInfo: { ...deviceInfo, ipHash: '' },
207→        });
208→        if (result) {
209→          useDeviceRegistryStore
210→            .getState()
211→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
212→        }
213→      } catch (error) {
214→        console.error('[Auth] Device registry init failed (non-blocking):', error);
215→      }
216→    })();
217→
218→    // Non-blocking bin initialization (fire-and-forget)
219→    // After old service creates/loads bin, also load into SDK for deleteToBin support
220→    void (async () => {
221→      try {
222→        await initializeBin({
223→          userPrivateKey: userKeypair.privateKey,
224→          userPublicKey: userKeypair.publicKey,
225→        });
226→        // Now load bin into SDK (old service ensures bin IPNS record exists)
227→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
228→        if (hasSdkClient()) {
229→          await getSdkClient().loadBin();
230→        }
231→      } catch (error) {
232→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
233→      }
234→    })();
235→
236→    // Non-blocking: fetch retention config from API
237→    void (async () => {
238→      try {
239→        const config = await vaultControllerGetConfig();
240→        if (config.recycleBinRetentionDays != null) {
241→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
242→        }
243→      } catch (error) {
244→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
245→      }
246→    })();
247→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
248→
249→  /**
250→   * Complete backend authentication after Core Kit login.
251→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
252→   * to the backend with loginType 'corekit'. The backend verifies it against
253→   * its own JWKS since CipherBox is the identity provider.
254→   */
255→  const completeBackendAuth = useCallback(
256→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
257→      // 1. Get real publicKey from Core Kit TSS export
258→      const publicKey = await getPublicKeyHex();
259→      if (!publicKey) {
260→        throw new Error('Failed to get publicKey from Core Kit');
261→      }
262→
263→      // publicKey available for debugging via DevTools if needed
264→
265→      // 2. Authenticate with CipherBox backend
266→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
267→      const response = await authApi.login({
268→        idToken: cipherboxJwt,
269→        publicKey,
270→        loginType: 'corekit',
271→      });
272→
273→      // 3. Store access token (refresh token in HTTP-only cookie)
274→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
275→      // are fully initialized to prevent Login.tsx from redirecting to /files
276→      // before the SDK client is ready for file operations.
277→      setAccessToken(response.accessToken);
278→
279→      // 4. Remember auth method for UX
280→      setLastAuthMethod(authMethod);
281→
282→      // 5. Initialize or load vault + SDK client
283→      await initializeOrLoadVault();
284→
285→      // 6. Now that vault keys are loaded and SDK is initialized,
286→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
287→      setAuthenticated();
288→    },
289→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
290→  );
291→
292→  /**
293→   * Complete the login flow after REQUIRED_SHARE is resolved.
294→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
295→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
296→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
297→   */
298→  const completeRequiredShare = useCallback(async (): Promise<void> => {
299→    // Read directly from Zustand store to get fresh values — this callback
300→    // may be called from useDeviceApproval's useAuth() instance, so we
301→    // can't rely on closure-captured selector values.
302→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
303→
304→    if (!jwt || !method) {
305→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
306→    }
307→
308→    // Core Kit should now be LOGGED_IN after inputFactorKey()
309→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
310→    await completeBackendAuth(method, jwt);
311→
312→    // NOW sync Core Kit React state to LOGGED_IN.
313→    // We deliberately delayed this from inputFactorKey() to prevent the session
314→    // restoration effect from firing before backend auth completed.
315→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
316→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
317→    syncStatus();
318→
319→    // Clear pending state
320→    setPendingAuth(null, null);
321→
322→    // Navigate to files
323→    navigate('/files');
324→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
325→
326→  /**
327→   * Login with Google OAuth token.
328→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
329→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
330→   */
331→  const loginWithGoogle = useCallback(
332→    async (googleIdToken: string): Promise<void> => {
333→      if (isLoggingIn) return;
334→      setIsLoggingIn(true);
335→      try {
336→        // 1. Core Kit login via CipherBox identity provider
337→        const {
338→          cipherboxJwt,
339→          email,
340→          userId,
341→          status: coreKitStatus,
342→        } = await coreKitLoginGoogle(googleIdToken);
343→
344→        if (coreKitStatus === 'required_share') {
345→          // MFA enabled but device factor missing.
346→          // Store pending auth info for later completion after factor input.
347→          setPendingAuth(cipherboxJwt, 'google');
348→
349→          // Obtain temporary backend access token so the new device can
350→          // call bulletin board API endpoints (device-approval/*).
351→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
352→          // state and we can't export the TSS key yet.
353→          const tempLoginResponse = await authApi.login({
354→            idToken: cipherboxJwt,
355→            publicKey: `pending-core-kit-${userId}`,
356→            loginType: 'corekit',
357→          });
358→          setAccessToken(tempLoginResponse.accessToken);
359→
360→          if (email) {
361→            setUserEmail(email);
362→          }
363→
364→          // Do NOT call completeBackendAuth() or navigate('/files')
365→          // The component tree will see isRequiredShare === true and
366→          // render recovery/approval UI.
367→          return;
368→        }
369→
370→        // Normal path: Core Kit logged in, proceed as before
371→        // 2. Complete backend auth + vault init
372→        await completeBackendAuth('google', cipherboxJwt);
373→
374→        // 3. Store email for UI display (returned from identity endpoint)
375→        if (email) {
376→          setUserEmail(email);
377→        }
378→
379→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
380→      } catch (error) {
381→        console.error('[useAuth] Google login failed:', error);
382→        throw error;
383→      } finally {
384→        setIsLoggingIn(false);
385→      }
386→    },
387→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
388→  );
389→
390→  /**
391→   * Login with Email OTP.
392→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
393→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
394→   */
395→  const loginWithEmail = useCallback(
396→    async (email: string, otp: string): Promise<void> => {
397→      if (isLoggingIn) return;
398→      setIsLoggingIn(true);
399→      try {
400→        // 1. Core Kit login via CipherBox identity provider
401→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
402→
403→        if (coreKitStatus === 'required_share') {
404→          setPendingAuth(cipherboxJwt, 'email');
405→
406→          const tempLoginResponse = await authApi.login({
407→            idToken: cipherboxJwt,
408→            publicKey: `pending-core-kit-${userId}`,
409→            loginType: 'corekit',
410→          });
411→          setAccessToken(tempLoginResponse.accessToken);
412→          setUserEmail(email);
413→          return;
414→        }
415→
416→        // Normal path
417→        await completeBackendAuth('email', cipherboxJwt);
418→        setUserEmail(email);
419→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
420→      } catch (error) {
421→        console.error('[useAuth] Email login failed:', error);
422→        throw error;
423→      } finally {
424→        setIsLoggingIn(false);
425→      }
426→    },
427→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
428→  );
429→
430→  /**
431→   * Login with Wallet (SIWE).
432→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
433→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
434→   */
435→  const loginWithWallet = useCallback(
436→    async (cipherboxJwt: string, userId: string): Promise<void> => {
437→      if (isLoggingIn) return;
438→      setIsLoggingIn(true);
439→      try {
440→        // 1. Core Kit login via CipherBox identity provider
441→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
442→
443→        if (coreKitStatus === 'required_share') {
444→          setPendingAuth(cipherboxJwt, 'wallet');
445→
446→          const tempLoginResponse = await authApi.login({
447→            idToken: cipherboxJwt,
448→            publicKey: `pending-core-kit-${userId}`,
449→            loginType: 'corekit',
450→          });
451→          setAccessToken(tempLoginResponse.accessToken);
452→          return;
453→        }
454→
455→        // Normal path
456→        await completeBackendAuth('wallet', cipherboxJwt);
457→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
458→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
459→        // inside it may still be pending. An explicit navigate here would fire AFTER
460→        // vault init completes — by which point the user may have navigated away from
461→        // the login page, causing a disruptive late redirect.
462→      } catch (error) {
463→        console.error('[useAuth] Wallet login failed:', error);
464→        throw error;
465→      } finally {
466→        setIsLoggingIn(false);
467→      }
468→    },
469→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
470→  );
471→
472→  /**
473→   * Legacy login() for backward compatibility with AuthButton.
474→   * With Core Kit, login requires specifying the auth method.
475→   * This will be replaced by the new Login UI in Plan 04.
476→   */
477→  const login = useCallback(async () => {
478→    // Plan 04 will build the new login UI with method selection.
479→    // For now, this is a no-op placeholder that AuthButton calls.
480→    console.warn(
481→      '[useAuth] login() called without method -- ' +
482→        'use loginWithGoogle() or loginWithEmail() instead. ' +
483→        'Plan 04 will provide the new Login UI.'
484→    );
485→  }, []);
486→
487→  // Complete logout: Backend -> Core Kit -> Clear state
488→  const logout = useCallback(async () => {
489→    if (isLoggingOut) return;
490→
491→    setIsLoggingOut(true);
492→    try {
493→      // 1. Call backend logout (clears cookie)
494→      if (accessToken) {
495→        try {
496→          await authApi.logout();
497→        } catch {
498→          // Ignore errors -- we'll clear state anyway
499→        }
500→      }
501→
502→      // 2. Logout Core Kit (clears session from localStorage)
503→      await coreKitLogout();
504→
505→      // 3. Clear all user-scoped stores (centralized helper)
506→      clearAllUserStores();
507→
508→      // 4. Navigate to login
509→      navigate('/');
510→    } catch (error) {
511→      console.error('[useAuth] Logout failed:', error);
512→      // Still clear state even if backend fails
513→      clearAllUserStores();
514→      navigate('/');
515→    } finally {
516→      setIsLoggingOut(false);
517→    }
518→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
519→
520→  // Keep function refs up-to-date for use in session restoration effect.
521→  // Using refs prevents the effect from re-firing when function identities change.
522→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
523→  coreKitLogoutRef.current = coreKitLogout;
524→
525→  // Session restoration: if Core Kit restores a session from localStorage
526→  // on init, we have LOGGED_IN status without going through login flow.
527→  // Complete backend auth + vault loading.
528→  useEffect(() => {
529→    const restoreSession = async () => {
530→      // Only restore if Core Kit has a session but we don't have
531→      // a backend access token yet
532→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
533→        restoringRef.current = true;
534→        setIsLoggingIn(true);
535→        try {
536→          // Try to refresh using the HTTP-only cookie first
537→          const response = await authApi.refresh();
538→          setAccessToken(response.accessToken);
539→
540→          // Restore email from backend if available
541→          if (response.email) {
542→            setUserEmail(response.email);
543→          }
544→
545→          // Load vault keys from Core Kit keypair + initialize SDK
546→          await initializeOrLoadVaultRef.current?.();
547→
548→          // Mark as authenticated only after vault + SDK are ready
549→          setAuthenticated();
550→        } catch {
551→          // No valid backend session -- user needs to re-login
552→          // Core Kit session exists but backend cookie expired
553→          // Clear Core Kit session to avoid inconsistent state
554→          try {
555→            await coreKitLogoutRef.current?.();
556→          } catch {
557→            // Ignore logout errors during cleanup
558→          }
559→        } finally {
560→          restoringRef.current = false;
561→          setIsLoggingIn(false);
562→        }
563→      }
564→    };
565→    restoreSession();
566→  }, [
567→    coreKitLoggedIn,
568→    isAuthenticated,
569→    isLoggingIn,
570→    setAccessToken,
571→    setAuthenticated,
572→    setUserEmail,
573→  ]);
574→
575→  return {
576→    isLoading,
577→    isAuthenticated,
578→    isRequiredShare,
579→    lastAuthMethod,
580→    userEmail,
581→    pendingAuthMethod,
582→    login,
583→    loginWithGoogle,
584→    loginWithEmail,
585→    loginWithWallet,
586→    completeRequiredShare,
587→    logout,
588→  };
589→}
