Replace the hand-written auth wrapper with re-exports from `@cipherbox/api-client`. Keep the file as a thin adapter since `useAuth.ts` and `lib/web3auth/hooks.ts` use `authApi.foo()` style calls extensively. Convert it to import from `@cipherbox/api-client` instead of using the local axios client.

```ts
import {
  authControllerLogin,
  authControllerRefresh,
  authControllerLogout,
  authControllerGetMethods,
  authControllerLinkMethod,
  authControllerUnlinkMethod,
  authControllerDeleteAccount,
  identityControllerGoogleLogin,
  identityControllerSendOtp,
  identityControllerVerifyOtp,
  identityControllerGetWalletNonce,
  identityControllerWalletLogin,
} from '@cipherbox/api-client';
import type { AuthMethodResponseDto } from '@cipherbox/api-client';

export type AuthMethod = AuthMethodResponseDto;

export const authApi = {
  login: (data: { idToken: string; publicKey: string; loginType: 'corekit' }) =>
    authControllerLogin(data),
  refresh: () => authControllerRefresh({} as any),  // web uses cookie, no body needed
  logout: () => authControllerLogout(),
  getMethods: () => authControllerGetMethods(),
  linkMethod: (data: ...) => authControllerLinkMethod(data),
  unlinkMethod: (methodId: string) => authControllerUnlinkMethod({ methodId }),
  deleteAccount: () => authControllerDeleteAccount({ confirmation: 'DELETE' }),
  identityGoogle: (googleIdToken: string, intent?: 'login' | 'link') =>
    identityControllerGoogleLogin({ idToken: googleIdToken, ...(intent && { intent }) }),
  identityEmailSendOtp: (email: string) => identityControllerSendOtp({ email }),
  identityEmailVerify: (email: string, otp: string, intent?: 'login' | 'link') =>
    identityControllerVerifyOtp({ email, otp, ...(intent && { intent }) }),
  identityWalletNonce: () => identityControllerGetWalletNonce(),
  identityWalletVerify: (data: { message: string; signature: string }) =>
    identityControllerWalletLogin(data),
