```

Be careful with the type mappings — check the actual DTO types from api-client models to ensure they match.

#### Step 5: Replace lib/api/vault.ts

Same pattern — thin adapter over api-client functions:
```ts
import {
  vaultControllerGetQuota,
  vaultControllerGetVault,
  vaultControllerInitializeVault,
} from '@cipherbox/api-client';

export const vaultApi = {
  getQuota: () => vaultControllerGetQuota(),
  getVault: () => vaultControllerGetVault(),
  initVault: (dto) => vaultControllerInitializeVault(dto),
};
```

#### Step 6: Replace lib/api/ipfs.ts

Keep the file but switch to using api-client functions. The upload needs progress tracking, which can be passed via the `options` parameter (it's `AxiosRequestConfig`):

```ts
import { ipfsControllerUpload, ipfsControllerUnpin, ipfsControllerGet } from '@cipherbox/api-client';
import type { AxiosProgressEvent, CancelToken } from '@cipherbox/api-client';

export type AddResponse = { cid: string; size: number; recorded: boolean };
export type DownloadProgressCallback = (loaded: number, total: number) => void;

export async function addToIpfs(
  encryptedFile: Blob,
  onProgress?: (percent: number) => void,
  cancelToken?: CancelToken
): Promise<AddResponse> {
  const result = await ipfsControllerUpload(
    { file: encryptedFile },
    {
      onUploadProgress: (event: AxiosProgressEvent) => {
        if (event.total && onProgress) {
          onProgress(Math.round((event.loaded * 100) / event.total));
        }
      },
      cancelToken,
    }
  );
  return { cid: result.cid, size: result.size, recorded: result.recorded };
}

export async function unpinFromIpfs(cid: string): Promise<void> {
  await ipfsControllerUnpin({ cid });
}

export async function fetchFromIpfs(cid: string, onProgress?: DownloadProgressCallback): Promise<Uint8Array> {
  // For progress tracking, we need streaming - use the api-client's axios instance directly
  // For simple case, use the generated function
  if (!onProgress) {
    const blob = await ipfsControllerGet(cid);
    const buffer = await blob.arrayBuffer();
    return new Uint8Array(buffer);
  }
  // With progress, use axios with onDownloadProgress
  const blob = await ipfsControllerGet(cid, {
    onDownloadProgress: (event: AxiosProgressEvent) => {
      if (event.total) {
        onProgress(event.loaded, event.total);
      }
    },
  });
  const buffer = await blob.arrayBuffer();
  return new Uint8Array(buffer);
}
```

#### Step 7: Remove lib/api/client.ts

Delete this file entirely. All its consumers now go through `@cipherbox/api-client`.

Also check for any test files related to `client.ts` — `apps/web/src/lib/api/__tests__/client-refresh.test.ts` should be removed or rewritten to test the new flow.

#### Step 8: Add useHealthCheck thin wrapper

Create `apps/web/src/hooks/useHealthCheck.ts`:
```ts
import { useQuery } from '@tanstack/react-query';
import { healthControllerCheck } from '@cipherbox/api-client';

export function useHealthCheck(options?: { enabled?: boolean }) {
  return useQuery({
    queryKey: ['health'],
    queryFn: () => healthControllerCheck(),
    ...options,
  });
}
```

Update the 2 consumers (`Login.tsx` and `StatusIndicator.tsx`) to use this hook.

#### Step 9: Update setApiClientConfig in useAuth.ts

In `useAuth.ts`, update the `setApiClientConfig` call to include `withCredentials` and `refreshAccessToken`:

```ts
setApiClientConfig({
  baseUrl: apiUrl,
  getAccessToken,
  withCredentials: true,
  refreshAccessToken: async () => {
    const response = await authControllerRefresh({} as any);
    const newToken = response.accessToken;
    useAuthStore.getState().setAccessToken(newToken);
    return newToken;
  },
});
```

IMPORTANT: `setApiClientConfig` is called in `initializeOrLoadVault()`. But auth API calls (login, refresh during session restore) happen BEFORE vault init. So we need to call `setApiClientConfig` EARLY — at app startup or at least before the first API call. Move it to the top of `useAuth` or into the app initialization.

Actually, looking at the code more carefully: `authApi.login()` and `authApi.refresh()` are called before `setApiClientConfig()`. These calls use the `apiClient` axios instance (from `lib/api/client.ts`), not the `@cipherbox/api-client` custom instance.

After this refactor, `authApi` will use `@cipherbox/api-client` functions, which call `customInstance`, which calls `getApiClientConfig()`. So we MUST call `setApiClientConfig()` before any auth API call.

The fix: call `setApiClientConfig()` in the module scope or in a useEffect that runs on mount, before any auth calls. Something like:

In `apps/web/src/lib/api-config.ts` (new file):
```ts
import { setApiClientConfig } from '@cipherbox/api-client';
import { useAuthStore } from '../stores/auth.store';

const apiUrl = import.meta.env.VITE_API_URL || (typeof window !== 'undefined' ? `${window.location.origin}/api` : '/api');

// Initialize api-client config at module load time.
// getAccessToken reads from Zustand store (initially null/empty, populated after login).
// refreshAccessToken calls the refresh endpoint using HTTP-only cookie.
setApiClientConfig({
  baseUrl: apiUrl,
  getAccessToken: async () => useAuthStore.getState().accessToken || '',
  withCredentials: true,
  refreshAccessToken: async () => {
    // Import dynamically to avoid circular dependency
    const { authControllerRefresh } = await import('@cipherbox/api-client');
    const response = await authControllerRefresh({} as any);
    useAuthStore.getState().setAccessToken(response.accessToken);
    return response.accessToken;
  },
});

export { apiUrl };
```

Then import this module early in `main.tsx` or at the top of `useAuth.ts`.

Wait, there's a circular dependency risk: `api-config.ts` imports from `@cipherbox/api-client` + stores. The auth store imports nothing from api-client. So it should be fine.

But the `refreshAccessToken` callback calls `authControllerRefresh`, which calls `customInstance`, which calls `getApiClientConfig()` — this is the same config being set up. Since config is already set by the time refreshAccessToken runs, this should work.

Actually, the 401 interceptor in instance.ts should NOT use `refreshAccessToken` for the `/auth/refresh` endpoint itself (to avoid infinite loops). That's already in the plan.

#### Step 10: Update apps/web/package.json

Make sure `@cipherbox/api-client` is in dependencies (it might only be used via `setApiClientConfig` currently). Check if it's already there.

#### Step 11: Clean up

- Remove any unused imports
- Remove `apps/web/src/lib/api/__tests__/` if tests are no longer relevant
- Run `pnpm --filter web build` to verify no type errors
- Run `pnpm lint` to check for issues

