163→        vaultKeypair: {
164→          publicKey: userKeypair.publicKey,
165→          privateKey: userKeypair.privateKey,
166→        },
167→        rootIpnsName: vaultState.rootIpnsName,
168→        rootFolderKey: vaultState.rootFolderKey,
169→        teeKeys: authState.teeKeys ?? undefined,
170→        shareCallbacks: {
