446→          const tempLoginResponse = await authApi.login({
447→            idToken: cipherboxJwt,
448→            publicKey: `pending-core-kit-${userId}`,
449→            loginType: 'corekit',
450→          });
451→          setAccessToken(tempLoginResponse.accessToken);
452→          return;
453→        }
454→
455→        // Normal path
456→        await completeBackendAuth('wallet', cipherboxJwt);
457→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
458→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
459→        // inside it may still be pending. An explicit navigate here would fire AFTER
460→        // vault init completes — by which point the user may have navigated away from
461→        // the login page, causing a disruptive late redirect.
462→      } catch (error) {
463→        console.error('[useAuth] Wallet login failed:', error);
464→        throw error;
465→      } finally {
466→        setIsLoggingIn(false);
467→      }
468→    },
469→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
470→  );
