178→
179→// ---------------------------------------------------------------------------
180→// Post-upload / post-create share key propagation
181→// ---------------------------------------------------------------------------
182→
183→/**
184→ * Ensure sent shares cache is fresh (fetched within last 30s).
185→ * Returns the current sent shares array.
186→ */
187→async function ensureFreshSentShares(): Promise<SentShare[]> {
188→  const store = useShareStore.getState();
189→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
190→    return store.sentShares;
191→  }
192→  // Re-wrapping needs the full set — paginate through all pages
193→  const allShares = await fetchAllSentShares();
194→  useShareStore.getState().setSentShares(allShares);
195→  return allShares;
196→}
197→
198→/**
199→ * Fetch ALL sent shares by paginating through the API.
200→ * The API enforces a max limit of 100 per page.
201→ */
202→async function fetchAllSentShares(): Promise<SentShare[]> {
203→  const pageSize = 100;
204→  let offset = 0;
205→  const allShares: SentShare[] = [];
206→
207→  while (true) {
208→    const { shares, total } = await fetchSentShares(pageSize, offset);
209→    allShares.push(...shares);
210→    offset += shares.length;
211→    if (offset >= total || shares.length === 0) break;
212→  }
213→
214→  return allShares;
215→}
216→
217→/**
218→ * Check if a folder (by IPNS name) has any active shares.
219→ * Used to decide whether post-upload re-wrapping is needed.
220→ */
221→export async function hasActiveShares(folderIpnsName: string): Promise<boolean> {
222→  const shares = await ensureFreshSentShares();
223→  return shares.some((s) => s.ipnsName === folderIpnsName);
224→}
225→
226→/**
227→ * Find active shares that cover a given folder, including ancestor shares.
228→ * A folder is "covered" if it or any of its ancestor folders is shared.
229→ *
230→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
231→ *
232→ * @param folderIpnsName - IPNS name of the current folder
233→ * @param folders - Current folder tree from the folder store
234→ * @param currentFolderId - ID of the current folder in the tree
235→ * @returns Array of sent shares covering this folder (may be from ancestor)
236→ */
237→export async function findCoveringShares(
238→  folderIpnsName: string,
239→  folders: Record<string, FolderNode>,
240→  currentFolderId: string | null
241→): Promise<SentShare[]> {
242→  const shares = await ensureFreshSentShares();
243→  if (shares.length === 0) return [];
244→
245→  // Collect all IPNS names from this folder up to root
246→  const ipnsNames = new Set<string>();
247→  ipnsNames.add(folderIpnsName);
248→
249→  let walkId = currentFolderId;
250→  while (walkId) {
251→    const node = folders[walkId];
252→    if (!node) break;
253→    ipnsNames.add(node.ipnsName);
254→    walkId = node.parentId;
255→  }
256→
257→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
258→}
259→
260→/**
261→ * After adding a file or subfolder to a shared folder, re-wrap the new key
262→ * for all existing share recipients.
263→ *
264→ * This is a fire-and-forget operation -- failures are logged but don't block
265→ * the primary upload/create flow.
266→ *
267→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
268→ * after this function completes. This function does NOT zero the keys because
269→ * some callers (e.g., subfolder creation) keep the key alive in the store.
270→ * Use a `finally` block to ensure zeroing even on errors.
271→ *
272→ * @param params.folderIpnsName - IPNS name of the folder being modified
273→ * @param params.folders - Current folder tree from the store
274→ * @param params.currentFolderId - ID of the current folder in the tree
275→ * @param params.newItems - New items whose keys need re-wrapping
276→ */
277→export async function reWrapForRecipients(params: {
278→  folderIpnsName: string;
279→  folders: Record<string, FolderNode>;
280→  currentFolderId: string | null;
281→  newItems: Array<{
282→    keyType: 'file' | 'folder';
283→    itemId: string;
284→    plaintextKey: Uint8Array;
285→  }>;
286→}): Promise<{ failedRecipients: string[] }> {
287→  const coveringShares = await findCoveringShares(
288→    params.folderIpnsName,
289→    params.folders,
290→    params.currentFolderId
291→  );
292→
293→  if (coveringShares.length === 0) return { failedRecipients: [] };
294→
295→  const failedRecipients: string[] = [];
296→
297→  // For each share recipient, re-wrap all new item keys
298→  for (const share of coveringShares) {
299→    try {
300→      const recipientPubKey = hexToBytes(
301→        share.recipientPublicKey.startsWith('0x')
302→          ? share.recipientPublicKey.slice(2)
303→          : share.recipientPublicKey
304→      );
305→
306→      const wrappedKeys: Array<{
307→        keyType: 'file' | 'folder';
308→        itemId: string;
309→        encryptedKey: string;
310→      }> = [];
311→
312→      for (const item of params.newItems) {
313→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
314→        wrappedKeys.push({
315→          keyType: item.keyType,
316→          itemId: item.itemId,
317→          encryptedKey: bytesToHex(wrapped),
318→        });
319→      }
320→
321→      // Add the wrapped keys to this share via API
322→      await addShareKeys(share.shareId, wrappedKeys);
323→    } catch (err) {
324→      console.warn(
325→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
326→        err
327→      );
328→      failedRecipients.push(share.recipientPublicKey);
329→    }
330→  }
331→
332→  return { failedRecipients };
333→}
334→
335→// ---------------------------------------------------------------------------
336→// Lazy key rotation after revocation
337→// ---------------------------------------------------------------------------
338→
339→/** A revoked share pending key rotation. */
340→export type PendingRotation = {
341→  shareId: string;
342→  recipientPublicKey: string;
343→  itemType: 'folder' | 'file';
344→  ipnsName: string;
345→  itemName: string;
346→  revokedAt: string;
347→};
348→
349→/**
350→ * Fetch revoked shares that are pending key rotation from the server.
351→ * These are shares where revokedAt is set but the share has not been hard-deleted.
352→ */
353→export async function fetchPendingRotations(): Promise<PendingRotation[]> {
354→  const response = await sharesControllerGetPendingRotations();
355→
356→  return response.map((r) => ({
357→    shareId: r.shareId,
358→    recipientPublicKey: r.recipientPublicKey,
359→    itemType: r.itemType as 'folder' | 'file',
360→    ipnsName: r.ipnsName,
361→    itemName: r.itemName,
362→    revokedAt: String(r.revokedAt),
363→  }));
364→}
365→
366→/**
367→ * Check if a folder has pending rotations (revoked shares awaiting key rotation).
368→ * Called before any folder modification.
369→ *
370→ * @param folderIpnsName - IPNS name of the folder being modified
371→ * @returns true if there are revoked shares for this folder that need rotation
372→ */
373→export async function checkPendingRotation(folderIpnsName: string): Promise<boolean> {
374→  const pendingRotations = await fetchPendingRotations();
375→  return pendingRotations.some((r) => r.ipnsName === folderIpnsName);
376→}
377→
378→/**
379→ * Update the encrypted key on a share record after lazy key rotation.
380→ * Re-wraps the new folder key for a remaining (non-revoked) recipient.
381→ */
382→export async function updateShareKey(shareId: string, encryptedKey: string): Promise<void> {
383→  await sharesControllerUpdateShareEncryptedKey(shareId, { encryptedKey });
384→}
385→
386→/**
387→ * Hard-delete a revoked share after rotation is complete.
388→ */
389→export async function completeShareRotation(shareId: string): Promise<void> {
390→  await sharesControllerCompleteRotation(shareId);
391→}
392→
393→/**
394→ * Execute lazy key rotation for a folder.
395→ * Called when a folder modification is about to happen and pending rotations exist.
396→ *
397→ * Protocol:
398→ * 1. Generate new random folderKey
399→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
400→ * 3. Update remaining shares with the new encrypted key
401→ * 4. Hard-delete revoked share records (rotation complete)
402→ * 5. Invalidate share cache
403→ *
404→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
405→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
406→ * since it has access to the folder's IPNS private key and publishing infrastructure.
407→ *
408→ * @returns The new folderKey for the caller to use
409→ */
410→export async function executeLazyRotation(params: {
411→  folderIpnsName: string;
412→  oldFolderKey: Uint8Array;
413→  ownerPublicKey: Uint8Array;
414→}): Promise<{ newFolderKey: Uint8Array }> {
415→  // 1. Generate new random 32-byte folderKey
416→  const newFolderKey = generateRandomBytes(32);
417→
418→  // 2. Fetch pending rotations and active shares for this folder
419→  const [pendingRotations, activeSentShares] = await Promise.all([
420→    fetchPendingRotations(),
421→    getSentSharesForItem(params.folderIpnsName),
422→  ]);
423→
424→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
425→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
426→
427→  // Active shares that are NOT revoked -- these recipients keep access
428→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
429→
430→  // 3. Re-wrap new folderKey for each remaining recipient
431→  const reWrapFailures: string[] = [];
432→  for (const share of remainingShares) {
433→    try {
434→      const recipientPubKey = hexToBytes(
435→        share.recipientPublicKey.startsWith('0x')
436→          ? share.recipientPublicKey.slice(2)
437→          : share.recipientPublicKey
438→      );
439→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
440→      await updateShareKey(share.shareId, bytesToHex(wrapped));
441→    } catch (err) {
442→      console.warn(
443→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
444→        err
445→      );
446→      reWrapFailures.push(share.shareId);
447→    }
448→  }
449→
450→  if (reWrapFailures.length > 0) {
451→    newFolderKey.fill(0);
452→    throw new Error(
453→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
454→        'Aborting to prevent inconsistent state.'
455→    );
456→  }
457→
458→  // 4. Hard-delete all revoked shares for this folder
459→  for (const revoked of revokedForFolder) {
460→    try {
461→      await completeShareRotation(revoked.shareId);
462→    } catch (err) {
463→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
464→    }
465→  }
466→
467→  // 5. Invalidate the sent shares cache so next check fetches fresh state
468→  useShareStore.getState().setSentShares([]);
469→
470→  return { newFolderKey };
471→}
