13→  const [showDialog, setShowDialog] = useState(false);
14→  const [isExporting, setIsExporting] = useState(false);
15→  const [error, setError] = useState<string | null>(null);
16→
17→  const handleExport = async () => {
18→    setIsExporting(true);
19→    setError(null);
20→
21→    try {
22→      const data = await vaultControllerExportVault();
23→
24→      // Trigger browser download
25→      const json = JSON.stringify(data, null, 2);
26→      const blob = new Blob([json], { type: 'application/json' });
27→      const url = URL.createObjectURL(blob);
28→
29→      const link = document.createElement('a');
30→      link.href = url;
31→      link.download = 'cipherbox-vault-export.json';
32→      document.body.appendChild(link);
33→      link.click();
34→      document.body.removeChild(link);
35→
36→      URL.revokeObjectURL(url);
37→      setShowDialog(false);
38→    } catch {
39→      setError('Export failed. Please try again.');
40→    } finally {
41→      setIsExporting(false);
42→    }
