70→      <ConfirmDialog
71→        open={showDialog}
72→        onClose={() => setShowDialog(false)}
73→        onConfirm={handleExport}
74→        title="export vault"
75→        message="This export contains encrypted keys for your entire vault. Anyone with this file AND your private key can access all your files. Store it securely -- external drive, password manager, or printed paper backup."
76→        confirmLabel="CONFIRM EXPORT"
77→        isDestructive={false}
78→        isLoading={isExporting}
