  1→import { useState, useCallback, useEffect, useRef } from 'react';
  2→import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/core';
  3→import { decryptFolderMetadata } from '@cipherbox/core';
  4→import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
  5→import { Modal } from '../ui/Modal';
  6→import { useAuthStore } from '../../stores/auth.store';
  7→import { useFolderStore } from '../../stores/folder.store';
  8→import {
  9→  sharesControllerCreateShare,
 10→  sharesControllerLookupUser,
 11→  sharesControllerGetSentShares,
 12→  sharesControllerRevokeShare,
 13→} from '../../api/shares/shares';
 14→import { resolveFileMetadata } from '../../services/file-metadata.service';
 15→import { resolveIpnsRecord } from '../../services/ipns.service';
 16→import { fetchFromIpfs } from '../../lib/api/ipfs';
 17→import type { CreateShareDtoItemType } from '../../api/models/createShareDtoItemType';
 18→import type { ChildKeyDto } from '../../api/models/childKeyDto';
 19→import { useShareStore } from '../../stores/share.store';
 20→import { collectChildKeys, reWrapEncryptedKey } from '../../lib/crypto/key-wrapping';
 21→import { InviteLinkTab } from './InviteLinkTab';
