 24→type ShareDialogProps = {
 25→  isOpen: boolean;
 26→  onClose: () => void;
 27→  item: FolderChild;
 28→  folderKey: Uint8Array;
 29→  ipnsName: string;
 30→  parentFolderId: string;
 31→};
 32→
 33→/** Sent share record from the API */
 34→type SentShare = {
 35→  shareId: string;
 36→  recipientPublicKey: string;
 37→  itemType: string;
 38→  ipnsName: string;
 39→  itemName: string;
 40→  createdAt: string;
 41→};
 42→
 43→/**
 44→ * Validate public key format: must be 0x04 prefix + 128 hex chars (64 bytes body = 65 bytes total uncompressed).
 45→ */
 46→function isValidPublicKey(key: string): boolean {
 47→  if (!key.startsWith('0x04')) return false;
 48→  // 0x + 130 hex chars = 65 bytes uncompressed secp256k1
 49→  const hexPart = key.slice(2);
 50→  if (hexPart.length !== 130) return false;
 51→  return /^[0-9a-fA-F]+$/.test(hexPart);
 52→}
 53→
 54→/**
 55→ * Truncate a public key for display: 0x{first4}...{last4}
 56→ */
 57→function truncateKey(key: string): string {
 58→  if (key.length < 12) return key;
 59→  const hex = key.startsWith('0x') ? key.slice(2) : key;
 60→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 61→}
 62→
 63→/**
 64→ * Share dialog modal for creating and managing shares.
 65→ *
 66→ * Allows users to:
 67→ * - Paste a recipient's public key and create a share
 68→ * - View existing recipients with truncated pubkeys
 69→ * - Revoke individual recipients with inline confirm
 70→ *
 71→ * For folders, traverses all descendants and re-wraps keys.
 72→ * For files, wraps the single file key for the recipient.
 73→ */
 74→export function ShareDialog({
 75→  isOpen,
 76→  onClose,
 77→  item,
 78→  folderKey,
 79→  ipnsName,
 80→  parentFolderId,
 81→}: ShareDialogProps) {
 82→  const [activeTab, setActiveTab] = useState<'direct' | 'invite'>('direct');
 83→  const [pubKeyInput, setPubKeyInput] = useState('');
 84→  const [error, setError] = useState<string | null>(null);
 85→  const [success, setSuccess] = useState<string | null>(null);
 86→  const [isSharing, setIsSharing] = useState(false);
 87→  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);
 88→  const [recipients, setRecipients] = useState<SentShare[]>([]);
 89→  const [recipientsLoading, setRecipientsLoading] = useState(false);
 90→  const [recipientsFetched, setRecipientsFetched] = useState(false);
 91→  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
 92→  const [revokingId, setRevokingId] = useState<string | null>(null);
 93→
 94→  const inputRef = useRef<HTMLInputElement>(null);
 95→  const directTabRef = useRef<HTMLButtonElement>(null);
 96→  const inviteTabRef = useRef<HTMLButtonElement>(null);
 97→
 98→  // Fetch existing recipients when dialog opens
 99→  useEffect(() => {
100→    if (!isOpen) {
101→      // Reset state on close
102→      setActiveTab('direct');
103→      setPubKeyInput('');
104→      setError(null);
105→      setSuccess(null);
106→      setIsSharing(false);
107→      setProgress(null);
108→      setConfirmRevokeId(null);
109→      setRevokingId(null);
110→      setRecipients([]);
111→      setRecipientsLoading(false);
112→      setRecipientsFetched(false);
113→      return;
114→    }
115→
116→    let cancelled = false;
117→    setRecipientsLoading(true);
118→
119→    (async () => {
120→      const pageSize = 100;
121→      let offset = 0;
122→      const allShares: SentShare[] = [];
123→
124→      // Paginate through all sent shares (API max 100 per page)
125→
126→      while (true) {
127→        const response = await sharesControllerGetSentShares({ limit: pageSize, offset });
128→        if (cancelled) return;
129→        const pageShares = response.shares
130→          .filter((s) => s.ipnsName === ipnsName)
131→          .map((s) => ({
132→            shareId: s.shareId,
133→            recipientPublicKey: s.recipientPublicKey,
134→            itemType: s.itemType as 'folder' | 'file',
135→            ipnsName: s.ipnsName,
136→            itemName: s.itemName,
137→            createdAt: String(s.createdAt),
138→          }));
139→        allShares.push(...pageShares);
140→        offset += response.shares.length;
141→        if (offset >= response.total || response.shares.length === 0) break;
142→      }
143→
144→      if (cancelled) return;
145→      setRecipients(allShares);
146→    })()
147→      .catch((err) => {
148→        if (cancelled) return;
149→        console.error('Failed to fetch sent shares:', err);
150→      })
151→      .finally(() => {
152→        if (!cancelled) {
153→          setRecipientsLoading(false);
154→          setRecipientsFetched(true);
155→        }
156→      });
157→
158→    return () => {
159→      cancelled = true;
160→    };
161→  }, [isOpen, ipnsName]);
162→
163→  const handleShare = useCallback(async () => {
164→    setError(null);
165→    setSuccess(null);
166→
167→    const key = pubKeyInput.trim();
168→
169→    // Validate format
170→    if (!isValidPublicKey(key)) {
171→      setError('invalid key format -- expected 0x04 + 128 hex chars');
172→      return;
173→    }
174→
175→    // Prevent sharing root folder
176→    if (parentFolderId === 'root' && item.type === 'folder') {
177→      // Check if item is the root folder itself (the one navigated to at root)
178→      const rootFolder = useFolderStore.getState().folders['root'];
179→      if (rootFolder && item.id === 'root') {
180→        setError('cannot share root folder');
181→        return;
182→      }
183→    }
184→
185→    // Check not sharing with yourself
186→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
187→    if (!vaultKeypair) {
188→      setError('vault keypair not available');
189→      return;
190→    }
191→
192→    const myPubKeyHex = '0x' + bytesToHex(vaultKeypair.publicKey);
193→    if (key.toLowerCase() === myPubKeyHex.toLowerCase()) {
194→      setError('cannot share with yourself');
195→      return;
196→    }
197→
198→    setIsSharing(true);
199→
200→    try {
201→      // Verify recipient is a registered user
202→      const lookup = await sharesControllerLookupUser({ publicKey: key });
203→      if (!lookup.exists) {
204→        setError('user not found');
205→        setIsSharing(false);
206→        return;
207→      }
208→    } catch {
209→      setError('lookup failed, please try again');
210→      setIsSharing(false);
211→      return;
212→    }
213→
214→    try {
215→      const recipientPubKeyBytes = hexToBytes(key.slice(2));
216→      const ownerPrivateKey = vaultKeypair.privateKey;
217→
218→      let encryptedKey: string;
219→      let childKeys: ChildKeyDto[] | undefined;
220→
221→      if (item.type === 'folder') {
222→        const folderEntry = item as FolderEntry;
223→
224→        // For folders shared from a parent, folderKey IS the folder's own key
225→        // (it's the folderKey passed as prop which is the parent's key --
226→        //  but the item is a FolderEntry child that has folderKeyEncrypted)
227→        // We need to use folderKeyEncrypted from the FolderEntry to get the actual folder key.
228→        // Wait -- the folderKey prop is the PARENT folder's key. The item's own key
229→        // is obtained by unwrapping folderKeyEncrypted from the FolderEntry.
230→        // Actually, looking at the plan more carefully:
231→        //   "For folders: folderKey is passed as prop"
232→        // But folderKey is the PARENT's key. For sharing a subfolder, we need the subfolder's key.
233→        // Let's check: if the item is a direct child folder, its folderKeyEncrypted
234→        // is wrapped with the owner's public key (ECIES). We unwrap it to get the folder's own key.
235→
236→        // Unwrap the folder's own key from its encrypted form
237→        const itemFolderKey = await unwrapKey(
238→          hexToBytes(folderEntry.folderKeyEncrypted),
239→          ownerPrivateKey
240→        );
241→
242→        try {
243→          // Wrap the folder key for the recipient
244→          const wrappedForRecipient = await wrapKey(itemFolderKey, recipientPubKeyBytes);
245→          encryptedKey = bytesToHex(wrappedForRecipient);
246→
247→          // Now traverse children and re-wrap descendant keys
248→          // First, resolve folder metadata to get children
249→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
250→          if (resolved) {
251→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
252→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
253→            const encrypted = JSON.parse(encryptedJson);
254→            const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);
255→
256→            setProgress({ current: 0, total: 0 });
257→
258→            childKeys = await collectChildKeys(
