/**
 * Health check hook wrapping the @cipherbox/api-client generated function
 * with @tanstack/react-query for auto-refetching and caching.
 *
 * Replaces the orval-generated useHealthControllerCheck react-query hook.
 */
import { useQuery } from '@tanstack/react-query';
import type { UseQueryOptions } from '@tanstack/react-query';
import { healthControllerCheck } from '@cipherbox/api-client';
import type { HealthControllerCheck200 } from '@cipherbox/api-client';

type HealthData = Awaited<ReturnType<typeof healthControllerCheck>>;

export function useHealthCheck(options?: {
  query?: Partial<UseQueryOptions<HealthData, void, HealthControllerCheck200>>;
}) {
  const { query: queryOptions } = options ?? {};

  return useQuery<HealthData, void, HealthControllerCheck200>({
    queryKey: ['health'],
    queryFn: () => healthControllerCheck(),
    ...queryOptions,
  });
}

/**
 * Auth API adapter -- thin wrapper over @cipherbox/api-client generated functions.
 *
 * Keeps the `authApi.foo()` call style used by useAuth.ts and web3auth/hooks.ts
 * while delegating all HTTP transport to the shared api-client package.
 */
import {
  authControllerLogin,
  authControllerRefresh,
  authControllerLogout,
  authControllerGetMethods,
  authControllerLinkMethod,
  authControllerUnlinkMethod,
  authControllerDeleteAccount,
  identityControllerGoogleLogin,
  identityControllerSendOtp,
  identityControllerVerifyOtp,
  identityControllerGetWalletNonce,
  identityControllerWalletLogin,
} from '@cipherbox/api-client';
import type {
  AuthMethodResponseDto,
  LoginResponseDto,
  TokenResponseDto,
  IdentityTokenResponseDto,
  LinkMethodDtoLoginType,
} from '@cipherbox/api-client';

// Re-export model type under original alias for backward compatibility
export type AuthMethod = AuthMethodResponseDto;

export const authApi = {
  /**
   * Authenticate user with Web3Auth ID token.
   * Backend verifies the idToken with appropriate JWKS endpoint based on loginType.
   * Refresh token is stored in HTTP-only cookie automatically.
   */
  login: (data: {
    idToken: string;
    publicKey: string;
    loginType: 'corekit';
  }): Promise<LoginResponseDto> => authControllerLogin(data),

  /**
   * Refresh access token using HTTP-only refresh token cookie.
   * The refresh token is automatically sent via withCredentials: true.
   * New refresh token is set in HTTP-only cookie by the backend.
   */
  refresh: (): Promise<TokenResponseDto> =>
    // DesktopRefreshDto.refreshToken is optional -- web uses HTTP-only cookie
    authControllerRefresh({}),

  /**
   * Logout and invalidate refresh token.
   * Clears HTTP-only cookie on backend.
   */
  logout: (): Promise<unknown> => authControllerLogout(),

  /**
   * Get all linked auth methods for the current user.
   */
  getMethods: (): Promise<AuthMethodResponseDto[]> => authControllerGetMethods(),

  /**
   * Link a new auth method to the current user account.
   */
  linkMethod: (data: {
    idToken: string;
    loginType: 'google' | 'email' | 'wallet';
    walletAddress?: string;
    siweMessage?: string;
    siweSignature?: string;
  }): Promise<AuthMethodResponseDto[]> =>
    authControllerLinkMethod({
      ...data,
      loginType: data.loginType as LinkMethodDtoLoginType,
    }),

  /**
   * Unlink an auth method from the current user account.
   * Cannot unlink the last remaining auth method.
   */
  unlinkMethod: (methodId: string): Promise<unknown> =>
    authControllerUnlinkMethod({ methodId }),

  /**
   * Permanently delete the authenticated user's account.
   * Requires confirmation string "DELETE".
   */
  deleteAccount: (): Promise<unknown> =>
    authControllerDeleteAccount({ confirmation: 'DELETE' }),

  // --- CipherBox Identity Provider endpoints ---

  /** Get CipherBox identity JWT via Google OAuth token */
  identityGoogle: (
    googleIdToken: string,
    intent?: 'login' | 'link',
  ): Promise<IdentityTokenResponseDto> =>
    identityControllerGoogleLogin({ idToken: googleIdToken, ...(intent && { intent }) }),

  /** Send email OTP */
  identityEmailSendOtp: (email: string): Promise<{ success: boolean }> =>
    identityControllerSendOtp({ email }) as Promise<{ success: boolean }>,

  /** Verify email OTP and get CipherBox identity JWT */
  identityEmailVerify: (
    email: string,
    otp: string,
    intent?: 'login' | 'link',
  ): Promise<IdentityTokenResponseDto> =>
    identityControllerVerifyOtp({ email, otp, ...(intent && { intent }) }),

  /** Get a SIWE nonce for wallet login */
  identityWalletNonce: (): Promise<{ nonce: string }> =>
    identityControllerGetWalletNonce() as Promise<{ nonce: string }>,

  /** Verify SIWE wallet signature and get CipherBox identity JWT */
  identityWalletVerify: (data: {
    message: string;
    signature: string;
  }): Promise<IdentityTokenResponseDto> => identityControllerWalletLogin(data),
};

/**
 * Vault API adapter -- thin wrapper over @cipherbox/api-client generated functions.
 *
 * Keeps the `vaultApi.foo()` call style used by useAuth.ts while delegating
 * all HTTP transport to the shared api-client package.
 */
import {
  vaultControllerGetQuota,
  vaultControllerGetVault,
  vaultControllerInitializeVault,
} from '@cipherbox/api-client';
import type {
  QuotaResponseDto,
  VaultResponseDto,
  InitVaultDto,
} from '@cipherbox/api-client';

export const vaultApi = {
  /** Get storage quota for the current user. */
  getQuota: (): Promise<QuotaResponseDto> => vaultControllerGetQuota(),

  /** Get vault data for the current user. */
  getVault: (): Promise<VaultResponseDto> => vaultControllerGetVault(),

  /** Initialize vault with encrypted keys. */
  initVault: (dto: InitVaultDto): Promise<VaultResponseDto> =>
    vaultControllerInitializeVault(dto),
};

/**
 * IPFS API adapter -- wraps @cipherbox/api-client generated functions
 * with upload progress tracking, cancel support, and download-as-Uint8Array.
 *
 * Upload progress and cancel tokens are passed via the options parameter
 * (AxiosRequestConfig) to the generated function. Download progress uses
 * the fetch ReadableStream API for streaming byte counts, falling back
 * to a simple arrayBuffer() call when no callback is provided.
 */
import {
  ipfsControllerUpload,
  ipfsControllerUnpin,
  ipfsControllerGet,
  getApiClientConfig,
} from '@cipherbox/api-client';
import type { AxiosProgressEvent, CancelToken } from '@cipherbox/api-client';

export type AddResponse = { cid: string; size: number; recorded: boolean };

export type DownloadProgressCallback = (loaded: number, total: number) => void;

/**
 * Upload encrypted file to IPFS via backend relay.
 * Uses axios for upload progress tracking and cancellation.
 */
export async function addToIpfs(
  encryptedFile: Blob,
  onProgress?: (percent: number) => void,
  cancelToken?: CancelToken,
): Promise<AddResponse> {
  const result = await ipfsControllerUpload(
    { file: encryptedFile },
    {
      onUploadProgress: (event: AxiosProgressEvent) => {
        if (event.total && onProgress) {
          onProgress(Math.round((event.loaded * 100) / event.total));
        }
      },
      cancelToken,
    },
  );

  return { cid: result.cid, size: result.size, recorded: result.recorded };
}

/**
 * Unpin file from IPFS via backend relay.
 */
export async function unpinFromIpfs(cid: string): Promise<void> {
  await ipfsControllerUnpin({ cid });
}

/**
 * Fetch encrypted file from IPFS via the API proxy.
 * Supports progress tracking for larger files using streaming ReadableStream.
 *
 * @param cid - IPFS CID of the file
 * @param onProgress - Optional callback for download progress
 * @returns Encrypted file content as Uint8Array
 */
export async function fetchFromIpfs(
  cid: string,
  onProgress?: DownloadProgressCallback,
): Promise<Uint8Array> {
  // Simple path: no progress tracking -- use the generated function directly
  if (!onProgress) {
    const blob = await ipfsControllerGet(cid);
    const buffer = await blob.arrayBuffer();
    return new Uint8Array(buffer);
  }

  // With progress tracking: use fetch with ReadableStream
  // (axios onDownloadProgress doesn't give reliable byte counts in the browser)
  const config = getApiClientConfig();
  const token = await config.getAccessToken();
  const response = await fetch(`${config.baseUrl}/ipfs/${cid}`, {
    headers: {
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    credentials: config.withCredentials ? 'include' : 'same-origin',
  });

  if (!response.ok) {
    throw new Error(`Failed to fetch from IPFS: ${response.status}`);
  }

  const contentLength = response.headers.get('Content-Length');
  if (!contentLength) {
    const buffer = await response.arrayBuffer();
    return new Uint8Array(buffer);
  }

  // Stream with progress
  const total = parseInt(contentLength, 10);
  const reader = response.body?.getReader();
  if (!reader) {
    throw new Error('ReadableStream not supported');
  }

  const chunks: Uint8Array[] = [];
  let loaded = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    chunks.push(value);
    loaded += value.length;
    onProgress(loaded, total);
  }

  // Combine chunks
  const result = new Uint8Array(loaded);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }

  return result;
}

